import React, { createContext, useState, useEffect } from 'react';
import { db } from '../db/db';
import { v4 as uuidv4 } from 'uuid';
import { useNavigate } from 'react-router-dom';
import proj4 from 'proj4';


export const MainContext = createContext();

export const MainProvider = ({ children }) => {
    // Définir les systèmes de projection
    const lambert93 = '+proj=lcc +lat_1=49 +lat_2=44 +lat_0=46.5 +lon_0=3 +x_0=700000 +y_0=6600000 +ellps=GRS80 +towgs84=0,0,0,0,0,0,0 +units=m +no_defs+proj=lcc +lat_1=49 +lat_2=44 +lat_0=46.5 +lon_0=3 +x_0=700000 +y_0=6600000 +ellps=GRS80 +towgs84=0,0,0,0,0,0,0 +units=m +no_defs';
    const wgs84 = 'EPSG:4326';
    const [loadingObs, setLoadingObs] = useState(false); // State to manage loading
    const [selectedSite, setSelectedSite] = useState(null);
    const [status, setStatus] = useState('');
    const [ssoLoading, setSsoLoading] = useState(() => new URLSearchParams(window.location.search).has('sso'));
    const [newSite, setNewsite] = useState(null);
    const [selectedSpecies, setSelectedSpecies] = useState(null);
    const [selectedStade, setSelectedStade] = useState(null);
    const [stadeEdit, setStadeEdit] = useState(null);
    const [clickedPosition, setClickedPosition] = useState(null);
    const [loading, setLoading] = useState(false);
    const [loadingEdit, setLoadingEdit] = useState(false);
    const [formData, setFormData] = useState({
        fiche: {
            lat: "",
            long: "",
            site: "",
            idsite: "",
            idcoord: "",
            newsite: "",
            date: "",
            date2: "",
            organisme: 2,
            etude: 0,
            typeDonnee: 'Pu',
            diffusion: 'Point',
            plusobser: "",
        },
        especes: {}
    });
    const [phase, setPhase] = useState('');
    const [user, setUser] = useState(null);
    const [obsCount, setObsCount] = useState(0);
    const [observatoireCount, setObservatoireCount] = useState(0);
    const [observateursCount, setObservateursCount] = useState(0);
    const [speciesCount, setSpeciesCount] = useState(0);
    const [siteCount, setSiteCount] = useState(0);
    const [communeCount, setCommuneCount] = useState(0);
    const [allParam, setAllParam] = useState('non');
    const navigate = useNavigate();
    const apiBaseUrl = process.env.REACT_APP_API_BASE_URL;

    // Fonction pour obtenir la date du jour au format 'YYYY-MM-DD'
    const getTodayDate = () => {
        return new Date().toISOString().split('T')[0];

    };

    // Initialisation des dates avec la date du jour
    useEffect(() => {
        setFormData(prevData => ({
            ...prevData,
            fiche: {
                ...prevData.fiche,
                date: getTodayDate(),
                date2: ''
            }
        }));
    }, []);

    // pour pouvoir réinitiliser les données
    const initialFormData = {
        fiche: {
            lat: "",
            long: "",
            site: "",
            idsite: "",
            idcoord: "",
            newsite: "",
            date: getTodayDate(),
            date2: '',
            organisme: '2',
            etude: 0,
            typeDonnee: 'Pu',
            diffusion: 'Point'
        },
        especes: {}
    };

    // Réinitialiser les données avec les dates du jour
    const resetFormData = () => {
        setFormData({
            ...initialFormData,
            fiche: {
                ...initialFormData.fiche,
                date: getTodayDate(),
                date2: '',
                organisme: '2',
            }
        });
    };

    //Mettre à jour le user
    useEffect(() => {
        fetchUser();
    }, []);

    // Connexion SSO : si ?sso=TOKEN est dans l'URL au démarrage
    useEffect(() => {
        const params = new URLSearchParams(window.location.search);
        const ssoToken = params.get('sso');
        if (!ssoToken) return;

        console.log('[SSO] Token détecté, longueur :', ssoToken.length);
        const ssoUrl = `${apiBaseUrl}/api/v1/verify_sso_token.php`;
        console.log('[SSO] URL appelée :', ssoUrl);

        (async () => {
            try {
                const response = await fetch(ssoUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ token: ssoToken }),
                });

                console.log('[SSO] Statut HTTP :', response.status);
                const text = await response.text();
                console.log('[SSO] Réponse brute :', text);

                let data;
                try {
                    data = JSON.parse(text);
                } catch {
                    console.error('[SSO] Réponse non-JSON reçue (erreur PHP probable)');
                    return;
                }

                console.log('[SSO] Réponse parsée :', data);

                if (data.statut === 'Ok') {
                    await db.user.clear();
                    await db.user.add({
                        nom: data.nom,
                        prenom: data.prenom,
                        idmembre: data.idmembre,
                        idobser: data.idobser,
                        droits: data.droits,
                    });
                    await fetchUser();
                    console.log('[SSO] Connexion réussie :', data.prenom, data.nom);
                    navigate('/', { replace: true });
                } else {
                    console.error('[SSO] Échec serveur :', data.message);
                }
            } catch (e) {
                console.error('[SSO] Erreur réseau (CORS ou serveur inaccessible) :', e.message);
            } finally {
                setSsoLoading(false);
            }
        })();
    }, []);

    const fetchUser = async () => {
        try {
            const users = await db.user.toArray();
            if (users.length > 0) {
                setUser(users[0]); // Supposons qu'il y a un seul utilisateur
            } else {
                setUser(null);
            }
        } catch (error) {
            console.error("Failed to fetch user from the database", error);
        }
    };

    // Fonction pour mettre à jour la phase
    const updatePhase = (newPhase) => {
        setPhase(newPhase);
        // On recompte le nombre d'obs dans la base
        const fetchObsCount = async () => {
            setLoading(true);
            try {
                const count = await db.obs.count();
                setObsCount(count);
            } catch (error) {
                console.error('Erreur lors de la récupération du nombre de lignes dans obs:', error);
            }
        };
        setLoading(false);
        fetchObsCount();
    };

    // Fonction pour mettre à jour `selectedSpecies`
    const updateSelectedSpecies = (species) => {
        setSelectedSpecies(species);
    };

    // Fonction pour mettre à jour `formData`
    const updateFormData = (newData) => {
        setFormData((prevData) => {
            const newFicheData = newData.fiche || {};
            const updatedFiche = {
                ...prevData.fiche,
                ...newFicheData
            };

            const updatedData = {
                ...prevData,
                fiche: updatedFiche
            };

            return updatedData;

        });
    };

    // Fonction pour ajouter ou mettre à jour une espèce dans `formData`
    const addOrUpdateSpecies = async (cdnom, observationData) => {
        const libstade = await fetchLibelleStade(observationData.stade);
        setFormData((prevFormData) => {
            const updatedFormData = { ...prevFormData };

            if (!updatedFormData.especes[cdnom]) {
                updatedFormData.especes[cdnom] = {
                    nom: observationData.nom,
                    cdnom: observationData.cdnom,
                    nomvern: observationData.nomvern,
                    observatoire: observationData.observatoire,
                    etude: parseInt(observationData.etude),
                    protocole: parseInt(observationData.protocole),
                    rqobs: observationData.rqobs,
                    nb: parseInt(observationData.maleCount + observationData.femaleCount + observationData.undeterminedCount),
                    photos: observationData.photos || [],
                    stades: {}
                };
            } else {
                updatedFormData.especes[cdnom].photos = observationData.photos || [];
            }

            updatedFormData.especes[cdnom].stades[observationData.stade] = {
                trouveMort: parseInt(observationData.trouveMort),
                mort: parseInt(observationData.mort),
                maleCount: observationData.maleCount,
                femaleCount: observationData.femaleCount,
                undeterminedCount: observationData.undeterminedCount,
                tdenom: observationData.tdenom,
                denom: observationData.denom,
                methode: parseInt(observationData.methode),
                protocole: parseInt(observationData.protocole),
                statutbio: parseInt(observationData.statutbio),
                comportement: parseInt(observationData.comportement),
                collecte: parseInt(observationData.collecte),
                stade: parseInt(observationData.stade),
                libstade: libstade || '',
                avescode: parseInt(observationData.avescode),
            };

            console.log('formData', formData)
            return updatedFormData;
        });
    };

    // Fonction pour ajouter ou mettre à jour un stade pour une espèce
    const addOrUpdateStade = async (cdnom, currentStade, stadeData) => {
        const libstade = await fetchLibelleStade(stadeData.stade);
        setFormData((prevFormData) => {
            const updatedFormData = { ...prevFormData };

            if (!updatedFormData.especes[cdnom]) {
                updatedFormData.especes[cdnom] = {
                    nom: stadeData.nom,
                    cdnom: stadeData.cdnom,
                    nomvern: stadeData.nomvern,
                    observatoire: stadeData.observatoire,
                    protocole: stadeData.protocole,
                    etude: stadeData.etude,
                    rqobs: stadeData.rqobs,
                    nb: parseInt(stadeData.maleCount + stadeData.femaleCount + stadeData.undeterminedCount),
                    stades: {}
                };
            }
            // Mettre à jour rqobs au niveau de l'espèce
            updatedFormData.especes[cdnom].rqobs = stadeData.rqobs;
            // Mettre à jour ou ajouter le nouveau stade
            updatedFormData.especes[cdnom].stades[stadeData.stade] = {
                ...stadeData,
                avescode: parseInt(stadeData.avescode) || 0,
                libstade: libstade || ''
            };
            // Supprimer l'ancien stade si la valeur du stade a changé
            if (currentStade !== stadeData.stade) {
                delete updatedFormData.especes[cdnom].stades[currentStade];
            }

            console.log('formData', updatedFormData);
            return updatedFormData;
        });
    };

    const fetchLibelleStade = async (stadeValue) => {
        try {
            const stadeId = Number(stadeValue);
            const stadeRecord = await db.stade.where('idstade').equals(stadeId).first();
            return stadeRecord ? stadeRecord.stade : null;
        } catch (error) {
            console.error(`Erreur lors de la récupération du libellé du stade pour la valeur ${stadeValue}:`, error);
            return null;
        }
    };

    const updateSpeciesPhotos = (cdnom, photos) => {
        setFormData((prevFormData) => {
            const updatedFormData = { ...prevFormData };
            if (updatedFormData.especes[cdnom]) {
                updatedFormData.especes[cdnom] = { ...updatedFormData.especes[cdnom], photos };
            }
            return updatedFormData;
        });
    };

    // Fonction pour supprimer une espèce dans `formData`
    const deleteSpecies = (cdnom) => {
        setFormData((prevFormData) => {
            const updatedFormData = { ...prevFormData };
            delete updatedFormData.especes[cdnom];
            return updatedFormData;
        });
    };

    // Fonction pour supprimer un stade pour une espèce
    const deleteStade = (cdnom, stade) => {
        setFormData((prevFormData) => {
            const updatedFormData = { ...prevFormData };
            if (updatedFormData.especes[cdnom] && updatedFormData.especes[cdnom].stades) {
                delete updatedFormData.especes[cdnom].stades[stade];
            }
            return updatedFormData;
        });
    };

    // Fonction pour éditer un stade pour une espèce
    const updateSelectedStade = (stadeData) => {
        setSelectedStade(stadeData);
    };

    //Enregistrement des données
    const saveFormData = async (formData) => {
        setLoadingObs(true);
        try {
            setLoading(true);
            if (!formData || !formData.fiche) {
                throw new Error("formData ou formData.fiche est indéfini");
            }
            if (formData.fiche.date2 == "") {
                formData.fiche.date2 = formData.fiche.date;
            }

            const ficheId = await db.fiche.add({
                codecom: formData.fiche.codecom || '',
                date: formData.fiche.date,
                datef: formData.fiche.date2,
                newsite: formData.fiche.newsite || false,
                flou: formData.fiche.flou || 0,
                hdeb: formData.fiche.hdeb || '',
                hfin: formData.fiche.hfin || '',
                iddep: formData.fiche.iddep || 0,
                idetude: formData.fiche.etude || 0,
                idfiche: formData.fiche.idfiche || 0,
                idorg: formData.fiche.organisme || 0,
                idsite: formData.fiche.idsite || null,
                idcoord: formData.fiche.idcoord || null,
                lat: formData.fiche.lat,
                lng: formData.fiche.long,
                site: formData.fiche.site || '',
                syn: formData.fiche.syn || 0,
                typedon: formData.fiche.typeDonnee,
                datesaisie: getTodayDate(),
                plusobser: formData.fiche.plusobser,
            });

            if (!formData.especes) {
                throw new Error("formData.especes est indéfini");
            }

            for (const cdnom in formData.especes) {
                const espece = formData.especes[cdnom];

                const obsId = await db.obs.add({
                    cdnom: cdnom,
                    idetude: formData.fiche.etude || 0,
                    idfiche: ficheId,
                    nomvern: espece.nomvern,
                    nom: espece.nom,
                    observa: espece.observatoire,
                    syn: espece.syn || 0,
                    idprotocole: espece.protocole,
                    rqobs: espece.rqobs,
                    nb: espece.nb,
                });

                if (espece.photos && espece.photos.length > 0) {
                    for (const photo of espece.photos) {
                        await db.obsphoto.add({
                            idobs: obsId,
                            idfiche: ficheId,
                            cdnom: cdnom,
                            photo,
                            datesaisi: getTodayDate(),
                            syn: 0,
                        });
                    }
                }

                for (const stadeId in espece.stades) {
                    const stade = espece.stades[stadeId];

                    await db.ligne.add({
                        idetatbio: stade.trouveMort === 1 ? 3 : 2,
                        idligne: stade.idligne || 0,
                        idobs: obsId,
                        idstade: stade.stade || 0,
                        idmethode: stade.methode || 0,
                        male: stade.maleCount,
                        femelle: stade.femaleCount,
                        ndiff: stade.undeterminedCount,
                        idpros: stade.collecte || 0,
                        stade: stade.stade || 0,
                        syn: stade.syn || 0,
                        tdenom: stade.tdenom || 'IND',
                        denom: stade.denom || 'Co',
                        idstbio: stade.statutbio || 0,
                        idcomp: stade.comportement || 0,
                        uuid: uuidv4(),
                        libstade: stade.libstade,
                        mort: stade.mort,
                        avescode: stade.avescode || '',
                    });
                }
            }

            console.log('Les données ont été enregistrées avec succès.')
            setLoadingObs(false);
            setLoading(false);
            setFormData(initialFormData);
            // On recompte le nombre d'obs dans la base
            const fetchObsCount = async () => {
                setLoading(true);
                try {
                    const count = await db.obs.count();
                    setObsCount(count);
                } catch (error) {
                    console.error('Erreur lors de la récupération du nombre de lignes dans obs:', error);
                }

                setLoading(false);
            };

            fetchObsCount();
        } catch (error) {
            console.error('Erreur lors de l\'enregistrement des données:', error);
        }
    };

    //Vérifie que les table dexie sont bien remplies
    const checkDbData = async () => {
        try {
            const tables = [
                'protocole',
                'site',
                'commune',
                'orga',
                'etude',
                'comportement',
                'methode',
                'occstatutbio',
                'occtype',
                'prospection',
                'stade',
                'observatoire',
                'species'
            ];

            const checks = await Promise.all(tables.map(async (table) => {
                const count = await db[table].count();
                return count > 0;
            }));

            return checks.every(Boolean) ? 'oui' : 'non';
        } catch (error) {
            console.error('Erreur lors de la vérification des tables:', error);
            return 'non';
        }
    };

    //formatage de formdata avc les données en base pour editer la fiche
    const fetchFicheDataById = async (idfiche) => {
        setLoadingEdit(true);
        try {
            // Récupérer la fiche spécifique depuis Dexie
            const fiche = await db.fiche.get(idfiche);

            if (!fiche) {
                throw new Error(`Fiche with idfiche ${idfiche} not found.`);
            }
            console.log('fiche', fiche)
            // Récupérer les observations liées à cette fiche
            const obs = await db.obs.where('idfiche').equals(fiche.id).toArray();


            // Préparer un objet pour les espèces dans formData
            const especes = {};

            // Récupérer les lignes liées à chaque observation
            const lignesPromises = obs.map(async (observation) => {
                const lignes = await db.ligne.where('idobs').equals(observation.id).toArray();

                console.log('lignes', lignes)
                const stades = {};

                lignes.forEach((ligne) => {
                    stades[ligne.stade] = {
                        trouveMort: ligne.idetatbio,
                        mort: ligne.mort,
                        maleCount: ligne.male || 0,
                        femaleCount: ligne.femelle || 0,
                        undeterminedCount: ligne.ndiff || 0,
                        tdenom: ligne.tdenom,
                        denom: ligne.denom,
                        methode: ligne.idmethode,
                        protocole: ligne.idpros,
                        statutbio: ligne.idstbio,
                        comportement: ligne.idcomp,
                        collecte: ligne.idpros,
                        stade: ligne.stade,
                        libstade: ligne.libstade,
                        avescode: parseInt(ligne.avescode) || 0,
                    };
                });

                const obsPhotos = await db.obsphoto.where('idobs').equals(observation.id).toArray();

                console.log('Stades for observation:', observation.cdnom, stades);
                especes[observation.cdnom] = {
                    nom: observation.nom,
                    cdnom: observation.cdnom,
                    nomvern: observation.nomvern,
                    observatoire: observation.observa,
                    etude: observation.idetude,
                    protocole: observation.idprotocole,
                    rqobs: observation.rqobs,
                    nb: observation.nb,
                    photos: obsPhotos.map((p) => p.photo),
                    stades: stades
                };
            });

            // Attendre la résolution de toutes les promesses dans lignesPromises
            await Promise.all(lignesPromises);
            // Construire l'objet formData avec les données récupérées
            const newFormData = {
                fiche: {
                    lat: fiche.lat,
                    long: fiche.lng,
                    date: fiche.date,
                    date2: fiche.datef,
                    organisme: fiche.idorg,
                    etude: fiche.idetude,
                    typeDonnee: fiche.typedon,
                    diffusion: fiche.syn,
                    plusobser: fiche.plusobser,
                },
                especes: especes
            };


            setFormData(newFormData);
            console.log('New FormData:', newFormData);

            // Supprimer les lignes, les observations et la fiche pour éviter les doublons
            const deletePromises = obs.map(async (observation) => {
                await db.ligne.where('idobs').equals(observation.id).delete();
                await db.obsphoto.where('idobs').equals(observation.id).delete();
                await db.obs.delete(observation.id);
            });

            await Promise.all(deletePromises);
            await db.fiche.delete(idfiche);

            setPhase('synthese');
            navigate('/saisi');
            setLoadingEdit(false);
        } catch (error) {
            console.error('Error fetching fiche data:', error);
        }
    };

    useEffect(() => {
        fetchCounts();
    }, []);


    async function fetchCounts() {
        const observatoireArray = await db.observatoire.toArray();
        setObservatoireCount(observatoireArray.length);
        const speciesArray = await db.species.toArray();
        setSpeciesCount(speciesArray.length);
        const communeArray = await db.commune.toArray();
        setCommuneCount(communeArray.length);
        const siteArray = await db.site.toArray();
        setSiteCount(siteArray.length);
        const observateursArray = await db.observateurs.toArray();
        setObservateursCount(observateursArray.length);
    }

    //pour créer un delai de pause
    function sleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    const handleUpdateAll = async () => {
        setLoading(true);
        console.log('handleUpdateAll called', loading);
        await handleUpdateObservatoireApiData();
        await handleUpdateSpeciesData();
        await handleUpdateParamData();
        await handleUpdateSiteData();
        await handleUpdateCommuneData();
        setLoading(false);
        setAllParam('oui');
        navigate("/");
    };

    async function handleUpdateObservatoireApiData() {
        setLoading(true);
        // Pause d'une demi seconde
        await sleep(500);
        try {
            await db.observatoire.clear();
            setStatus('Base de données des observatoires vidée');

            const response = await fetch(`${apiBaseUrl}/api/v1/aggregator`);
            const data = await response.json();

            const observatoireData = Object.values(data).map((item) => ({
                titre: item.titre,
                metakey: item.metakey,
                icon: item.icon,
                couleur: item.couleur,
                nomvar: item.nomvar,
                nom: item.nom,
                nomdeux: item.nomdeux,
                latin: item.latin,
                indice: item.indice,
                saisie: item.saisie,
                categorie: item.categorie,
                description: item.description
            }));

            await db.observatoire.bulkAdd(observatoireData);
            setStatus('Données des observatoires API chargées avec succès');
            fetchCounts();
        } catch (error) {
            setStatus(`Erreur lors de la mise à jour des données de l'API : ${error}`);
        }
        setLoading(false);
    }

    async function handleUpdateSpeciesData() {
        setLoading(true);
        // Pause d'une demi seconde
        await sleep(500);
        try {
            await db.species.clear();
            setStatus('Base de données des espèces vidée');

            const response = await fetch(`${apiBaseUrl}/api/v1/especes`);
            const data = await response.json();

            const speciesData = Object.values(data).map((item) => ({
                cdnom: item.cdnom,
                nom: item.nom,
                nomvern: item.nomvern,
                observatoire: item.observatoire,
                rang: item.rang
            }));

            await db.species.bulkAdd(speciesData);
            setStatus('Données des espèces chargées avec succès');
            fetchCounts();
        } catch (error) {
            setStatus(`Erreur lors de la mise à jour des données de l'API : ${error}`);
        }
        setLoading(false);
    }

    async function handleUpdateParamData() {
        setLoading(true);
        // Pause d'une demi seconde
        await sleep(500);
        try {
            await db.etude.clear();
            await db.protocole.clear();
            await db.orga.clear();
            await db.comportement.clear();
            await db.methode.clear();
            await db.occstatutbio.clear();
            await db.occtype.clear();
            await db.prospection.clear();
            await db.stade.clear();
            setStatus('Bases de données vidées');

            const response = await fetch(`${apiBaseUrl}/api/v1/param`);
            const data = await response.json();

            const protocoleData = data.protocole.map((item) => ({
                idprotocole: item.idprotocole,
                protocole: item.protocole
            }));

            const organismeData = data.organisme.map((item) => ({
                idorg: item.idorg,
                organisme: item.organisme
            }));

            const comportementData = data.comportement.map((item) => ({
                idcomp: item.idcomp,
                libcomp: item.libcomp
            }));

            const methodeData = data.methode.map((item) => ({
                idmethode: item.idmethode,
                methode: item.methode
            }));

            const occstatutbioData = data.occstatutbio.map((item) => ({
                idstbio: item.idstbio,
                statutbio: item.statutbio
            }));

            const occtypeData = data.occtype.map((item) => ({
                tdenom: item.tdenom,
                typedenom: item.typedenom
            }));

            const prospectionData = data.prospection.map((item) => ({
                idpros: item.idpros,
                prospection: item.prospection
            }));

            const etudeData = data.etude.map((item) => ({
                idetude: item.idetude,
                etude: item.etude
            }));

            const stadeData = data.stade.map((item) => ({
                idstade: item.idstade,
                stade: item.stade
            }));

            await db.protocole.bulkAdd(protocoleData);
            await db.orga.bulkAdd(organismeData);
            await db.etude.bulkAdd(etudeData);
            await db.comportement.bulkAdd(comportementData);
            await db.methode.bulkAdd(methodeData);
            await db.occstatutbio.bulkAdd(occstatutbioData);
            await db.occtype.bulkAdd(occtypeData);
            await db.prospection.bulkAdd(prospectionData);
            await db.stade.bulkAdd(stadeData);

            setStatus('Données des paramètres API chargées avec succès');
            fetchCounts();
        } catch (error) {
            setStatus(`Erreur lors de la mise à jour des données de l'API : ${error}`);
        }
        setLoading(false);
    }

    async function handleUpdateSiteData() {
        setLoading(true);
        // Pause d'une demi seconde
        await sleep(500);
        try {
            await db.site.clear();
            await db.observateurs.clear();
            setStatus('Bases de données vidées');

            const response = await fetch(`${apiBaseUrl}/api/v1/site`);
            const data = await response.json();

            const observateursData = data.observateurs.map((item) => ({
                idobser: item.idobser,
                observateur: item.observateur,
                nom: item.nom,
                prenom: item.prenom
            }));

            const siteData = data.site.map((item) => ({
                idsite: item.idsite,
                idcoord: item.idcoord,
                codecom: item.codecom,
                site: item.site,
                idparent: item.idparent,
                wsite: item.wsite,
                typestation: item.typestation,
                idstatus: item.idstatus,
                x: item.x,
                y: item.y,
                altitude: item.altitude,
                lat: item.lat,
                lng: item.lng,
                codel93: item.codel93,
                utm: item.utm,
                utm1: item.utm1,
                codel935: item.codel935,
                codel931: item.codel931
            }));

            await db.site.bulkAdd(siteData);
            await db.observateurs.bulkAdd(observateursData);

            setStatus('Données des sites chargées avec succès');
            fetchCounts();
        } catch (error) {
            setStatus(`Erreur lors de la mise à jour des données de l'API : ${error}`);
        }
        setLoading(false);
    }

    async function handleUpdateCommuneData() {
        setLoading(true);
        // Pause d'une demi seconde
        await sleep(500);
        try {
            // Nettoyez les bases de données existantes
            await db.commune.clear();
            await db.geojson.clear(); // Vider la table 'geojson' si elle existe
            setStatus('Bases de données vidées');

            // Récupérez les données depuis l'API
            const response = await fetch(`${apiBaseUrl}/api/v1/commune`);
            const data = await response.json();

            // Préparer les projections
            const lambert93 = "+proj=lcc +lat_1=49 +lat_2=44 +lat_0=46.5 +lon_0=3 +x_0=700000 +y_0=6600000 +ellps=GRS80 +towgs84=0,0,0,0,0,0,0 +units=m +no_defs";
            const wgs84 = "+proj=longlat +ellps=WGS84 +datum=WGS84 +no_defs";

            // Préparez les données pour la table 'commune'
            const communeData = Object.values(data).map((item) => ({
                codecom: item.codecom,
                commune: item.commune,
                poly: item.poly,
                geojson: item.geojson, // Coordonnées brutes
            }));
            // Transformez les coordonnées en WGS84
            const multiPolygon = Object.values(data).map((item) => {
                const rawCoordinates = JSON.parse(item.geojson); // Coordonnées brutes
                return rawCoordinates.map((polygon) =>
                    polygon.map((coord) => {
                        const [lng, lat] = proj4(lambert93, wgs84, coord); // Conversion Lambert93 → WGS84
                        return [lat, lng]; // Inverser lng/lat pour obtenir [lat, lng]
                    })
                );
            });

            // Stockez les données dans les tables Dexie
            await db.commune.bulkAdd(communeData); // Ajouter les données des communes
            await db.geojson.add(multiPolygon); // Ajouter le MultiPolygon dans la table 'geojson'

            // Mettez à jour l'état
            setStatus('Données des communes chargées avec succès');
            fetchCounts(); // Mettez à jour les compteurs
        } catch (error) {
            // Gestion des erreurs
            setStatus(`Erreur lors de la mise à jour des données de l'API : ${error}`);
        }
        setLoading(false);
    }

    return (
        <MainContext.Provider value={{
            checkDbData,
            selectedSpecies,
            selectedStade,
            formData,
            setSelectedSpecies: updateSelectedSpecies,
            setSelectedStade: updateSelectedStade,
            setFormData: updateFormData,
            addOrUpdateSpecies,
            phase,
            setPhase: updatePhase,
            updateFormData,
            setClickedPosition,
            clickedPosition,
            addOrUpdateStade,
            updateSpeciesPhotos,
            deleteSpecies,
            deleteStade,
            saveFormData,
            user,
            fetchUser,
            obsCount,
            setObsCount,
            fetchFicheDataById,
            setSelectedSite,
            selectedSite,
            newSite,
            setNewsite,
            loadingObs,
            loadingEdit,
            status,
            setStatus,
            handleUpdateAll,
            handleUpdateCommuneData,
            handleUpdateObservatoireApiData,
            handleUpdateParamData,
            handleUpdateSiteData,
            handleUpdateSpeciesData,
            fetchCounts,
            siteCount,
            speciesCount,
            observateursCount,
            observatoireCount,
            communeCount,
            allParam, setAllParam,
            loading, setLoading,
            ssoLoading,

        }}>
            {children}
        </MainContext.Provider>
    );
};
