import React, { useState, useEffect, useContext } from 'react';
import {
    Card, TextField, FormControl, InputLabel,
    Select, MenuItem, Button, Box, Typography, Autocomplete, Grid, Switch,
    IconButton, InputAdornment, Divider, Fab, Dialog, DialogTitle, DialogContent,
    DialogActions,
    FormControlLabel,
    FormLabel
} from '@mui/material';
import { db } from '../db/db';
import { MainContext } from '../context/MainContext';
import InfoIcon from '@mui/icons-material/Info';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import CameraAltIcon from '@mui/icons-material/CameraAlt';
import PhotoLibraryIcon from '@mui/icons-material/PhotoLibrary';
import CloseIcon from '@mui/icons-material/Close';
import aves from '../db/aves.json';

const compressImage = (file, maxWidth = 1200, quality = 0.7) =>
    new Promise((resolve) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let { width, height } = img;
                if (width > maxWidth) {
                    height = Math.round((height * maxWidth) / width);
                    width = maxWidth;
                }
                canvas.width = width;
                canvas.height = height;
                canvas.getContext('2d').drawImage(img, 0, 0, width, height);
                resolve(canvas.toDataURL('image/jpeg', quality));
            };
            img.src = e.target.result;
        };
        reader.readAsDataURL(file);
    });


const ObservationForm = ({ speciesOptions }) => {
    const { formData, setFormData, addOrUpdateSpecies, setPhase } = useContext(MainContext);
    const [selectedSpecies, setSelectedSpecies] = useState(null);
    const [observationData, setObservationData] = useState({
        collecte: 0,
        comportement: 0,
        tdenom: 'IND',
        methode: 0,
        mort: 0,
        protocole: 0,
        stade: 0,
        statutbio: 0,
        denom: 'Co',
        avescode: '',
    });
    const [stadeOptions, setStadeOptions] = useState([]);
    const [collecteOptions, setCollecteOptions] = useState([]);
    const [comportementOptions, setComportementOptions] = useState([]);
    const [denomOptions, setDenomOptions] = useState([]);
    const [methodeOptions, setMethodeOptions] = useState([]);
    const [mortOptions, setMortOptions] = useState([]);
    const [protocoleOptions, setProtocoleOptions] = useState([]);
    const [statutbioOptions, setStatutbioOptions] = useState([]);
    const [trouveMort, setTrouveMort] = useState(0);
    const [mort, setMort] = useState('');
    const [stade, setStade] = useState('');
    const [maleCount, setMaleCount] = useState(0);
    const [femaleCount, setFemaleCount] = useState(0);
    const [undeterminedCount, setUndeterminedCount] = useState(0);
    const [denom, setDenom] = useState(['Co']);
    const [open, setOpen] = useState(false);
    const [avesList, setAvesList] = useState([]);
    const [selectedAvesCode, setSelectedAvesCode] = useState('');
    const [isOrnitho, setIsOrnitho] = useState(false);
    const [photos, setPhotos] = useState([]);

    // Mette à jour le gestionnaire de changement d'espèce   
    const handleSpeciesChange = async (event, value) => {
        setSelectedSpecies(value);
        if (value) {
            const observatoire = value.observatoire;
            const observatoireData = await db.observatoire.where('nomvar').equals(observatoire).toArray();
            const observatoireOptions = observatoireData[0]?.saisie || {};
            const newStadeOptions = Object.entries(observatoireOptions.stade || {}).map(([label, value]) => ({ label, value }));
            const newCollecteOptions = Object.entries(observatoireOptions.collecte || {}).map(([label, value]) => ({ label, value }));
            const newComportementOptions = Object.entries(observatoireOptions.comportement || {}).map(([label, value]) => ({ label, value }));
            const newDenomOptions = Object.entries(observatoireOptions.denom || {}).map(([label, value]) => ({ label, value }));
            const newMethodeOptions = Object.entries(observatoireOptions.methode || {}).map(([label, value]) => ({ label, value }));
            const newMortOptions = Object.entries(observatoireOptions.mort || {}).map(([label, value]) => ({ label, value }));
            const newProtocoleOptions = Object.entries(observatoireOptions.protocole || {}).map(([label, value]) => ({ label, value }));
            const newStatutbioOptions = Object.entries(observatoireOptions.statutbio || {}).map(([label, value]) => ({ label, value }));

            setStadeOptions(newStadeOptions);
            setCollecteOptions(newCollecteOptions);
            setComportementOptions(newComportementOptions);
            setDenomOptions(newDenomOptions);
            setMethodeOptions(newMethodeOptions);
            setMortOptions(newMortOptions);
            setProtocoleOptions(newProtocoleOptions);
            setStatutbioOptions(newStatutbioOptions);
            setSelectedAvesCode('')

            // Définir les valeurs par défaut pour chaque champ
            setObservationData({
                collecte: newCollecteOptions.length > 0 ? newCollecteOptions[0].value : 0,
                comportement: newComportementOptions.length > 0 ? newComportementOptions[0].value : 0,
                tdenom: newDenomOptions.length > 0 ? newDenomOptions[0].value : 0,
                methode: newMethodeOptions.length > 0 ? newMethodeOptions[0].value : 0,
                mort: newMortOptions.length > 0 ? newMortOptions[0].value : 0,
                protocole: newProtocoleOptions.length > 0 ? newProtocoleOptions[0].value : 0,
                stade: newStadeOptions.length > 0 ? newStadeOptions[0].value : 0,
                statutbio: newStatutbioOptions.length > 0 ? newStatutbioOptions[0].value : 0,
                rqobs: '',
                avescode: '',
            });
            // vérifie que c'est de l'ornitho pour charger la liste des codes nivheurs
            if (observatoire === 'ornitho') {
                setIsOrnitho(true);
                setAvesList(aves);
            } else {
                setIsOrnitho(false);
                setAvesList([]);
            }
        }
    };

    // Définir les options de dénombrement
    const denomOpt = [
        { value: 'Co', label: 'Compté' },
        { value: 'Es', label: 'Estimé' },
    ];

    // Mettre à jour les valeurs par défaut à chaque changement d'options
    useEffect(() => {
        if (selectedSpecies) {
            setObservationData((prevData) => ({
                collecte: collecteOptions.length > 0 ? collecteOptions[0].value : 0,
                comportement: comportementOptions.length > 0 ? comportementOptions[0].value : 0,
                tdenom: denomOptions.length > 0 ? denomOptions[0].value : 0,
                denom: denomOpt.length > 0 ? denomOpt[0].value : 0,
                methode: methodeOptions.length > 0 ? methodeOptions[0].value : 0,
                mort: mortOptions.length > 0 ? mortOptions[0].value : 0,
                protocole: protocoleOptions.length > 0 ? protocoleOptions[0].value : 0,
                stade: stadeOptions.length > 0 ? stadeOptions[0].value : 0,
                statutbio: statutbioOptions.length > 0 ? statutbioOptions[0].value : 0,
                rqobs: '',
                avescode: '',
            }));
        }
    }, [stadeOptions, collecteOptions, comportementOptions, denomOptions, methodeOptions, mortOptions, protocoleOptions, statutbioOptions, selectedSpecies]);


    const handleSubmit = () => {
        // Construction des données d'observation pour un stade spécifique
        const formattedObservationData = {
            nom: selectedSpecies.nom,
            cdnom: selectedSpecies.cdnom,
            nomvern: selectedSpecies.nomvern,
            rqobs: observationData.rqobs,
            observatoire: selectedSpecies.observatoire,
            stade: observationData.stade,
            trouveMort,
            mort: trouveMort ? observationData.mort : 0,
            maleCount,
            femaleCount,
            undeterminedCount,
            denom: observationData.denom,
            tdenom: observationData.tdenom,
            methode: observationData.methode,
            protocole: observationData.protocole,
            statutbio: observationData.statutbio,
            comportement: observationData.comportement,
            collecte: observationData.collecte,
            avescode: observationData.avescode,
            photos,
        };

        console.log('formattedObservationData', formattedObservationData);
        // Utilisation de `addOrUpdateSpecies` pour ajouter ou mettre à jour l'espèce dans `formData`
        addOrUpdateSpecies(selectedSpecies.cdnom, formattedObservationData);

        setPhase('synthese');
    };

    const onCancel = () => {
        setPhase('fiche');
    };
    const onSynthese = () => {
        setPhase('synthese');
    };

    // Fonction pour ouvrir le dialogue
    const handleOpenDialog = () => {
        setOpen(true);
    };

    // Fonction pour fermer le dialogue
    const handleCloseDialog = () => {
        setOpen(false);
    };

    const isDenomIndOrNsp = observationData.tdenom === 'IND' || observationData.tdenom === 'NSP';
    useEffect(() => {
        if (isDenomIndOrNsp) {
            setMaleCount(0);
            setFemaleCount(0);
        }
    }, [isDenomIndOrNsp]);

    const handlePhotoCapture = async (e) => {
        const files = Array.from(e.target.files);
        const compressed = await Promise.all(files.map((f) => compressImage(f)));
        setPhotos((prev) => [...prev, ...compressed].slice(0, 5));
        e.target.value = '';
    };

    const removePhoto = (index) => {
        setPhotos((prev) => prev.filter((_, i) => i !== index));
    };

    const handleAvesChange = (selectedItem) => {
        if (!selectedItem || !selectedItem.code || !selectedItem.libelle) {
            console.error('Les données sélectionnées sont invalides :', selectedItem);
            return;
        }

        setObservationData(prev => ({
            ...prev,
            avescode: selectedItem.code
        }));
    };

    return (
        <Box sx={{
            minHeight: '100vh', paddingTop: 1,
            background: 'linear-gradient(135deg, #cce0dc, #ebfffd)',
        }}>
            <Card sx={{ padding: 2, paddingBottom: 20, }}>
                {/* Bouton pour ouvrir le dialogue */}
                <Fab size="small" color="jaune" aria-label="help" onClick={handleOpenDialog}
                    style={{ position: 'fixed', bottom: 100, left: 16 }}>
                    <HelpOutlineIcon />
                </Fab>
                {/* Dialogue pour afficher les conseils */}
                <Dialog open={open} onClose={handleCloseDialog}>
                    <DialogTitle>Conseils d'utilisation</DialogTitle>
                    <DialogContent>
                        <Typography variant="body2">Vous n'êtes pas obligé de remplir tous les champs</Typography>
                        <Typography variant="body2">Vous pourrez ajuster les valeurs mâles/femelles/indéterminé plus tard</Typography>
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={handleCloseDialog}>Fermer</Button>
                    </DialogActions>
                </Dialog>
                <Typography variant="body2">{formData.coordonnee}</Typography>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <FormControl fullWidth>
                            <Autocomplete
                                options={speciesOptions}
                                getOptionLabel={(option) => option.nom + " (" + option.nomvern + ")"}
                                onChange={handleSpeciesChange}
                                renderInput={(params) => <TextField {...params}
                                    label="Espèce" variant="outlined" margin="normal"
                                    required // Champ obligatoire
                                    helperText={!selectedSpecies ? 'Renseigner un espèce' : ''} // Message d'erreur
                                    InputProps={{
                                        ...params.InputProps,
                                        style: { fontSize: '0.875rem' },
                                    }}
                                    InputLabelProps={{ style: { fontSize: '0.875rem' } }}
                                />}
                            />
                        </FormControl>
                    </Grid>
                    {selectedSpecies && (
                        <>
                            <Grid item xs={6}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Stade</InputLabel>
                                    <Select
                                        value={observationData.stade || ""}
                                        onChange={(e) => setObservationData({ ...observationData, stade: e.target.value })}
                                        label="Stade"
                                        variant="outlined"
                                        sx={{ width: '90%' }}
                                    >
                                        {stadeOptions.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={6}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Méthode d'observation</InputLabel>
                                    <Select
                                        value={observationData.methode || ""}
                                        onChange={(e) => setObservationData({ ...observationData, methode: e.target.value })}
                                        label="Méthode"
                                        variant="outlined"
                                        sx={{ width: '90%' }}
                                    >
                                        {methodeOptions.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Type de dénombrement</InputLabel>
                                    <Select
                                        value={observationData.tdenom || ""}
                                        onChange={(e) => setObservationData({ ...observationData, tdenom: e.target.value })}
                                        label="Dénomination"
                                        variant="outlined"
                                        sx={{ width: '90%' }}
                                    >
                                        {denomOptions.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Dénombrement</InputLabel>
                                    <Select
                                        value={observationData.denom || ""}
                                        onChange={(e) => setObservationData({ ...observationData, denom: e.target.value })}
                                        label="Dénombrement"
                                        sx={{ width: '90%' }}
                                    >
                                        <MenuItem value="" disabled style={{ fontSize: '0.875rem' }}>
                                            Sélectionnez une option
                                        </MenuItem>
                                        {denomOpt.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={4}>
                                <TextField
                                    type="number"
                                    label="Mâle"
                                    value={maleCount || ""}
                                    inputProps={{ min: 0, style: { fontSize: '0.875rem' } }}
                                    onChange={(e) => setMaleCount(parseInt(e.target.value))}
                                    fullWidth
                                    sx={{ marginTop: 2 }}
                                    disabled={!isDenomIndOrNsp}
                                    InputLabelProps={{ style: { fontSize: '0.875rem' } }}
                                />
                            </Grid>
                            <Grid item xs={4}>
                                <TextField
                                    type="number"
                                    label="Femelle"
                                    value={femaleCount || ""}
                                    inputProps={{ min: 0, style: { fontSize: '0.875rem' } }}
                                    onChange={(e) => setFemaleCount(parseInt(e.target.value))}
                                    fullWidth
                                    sx={{ marginTop: 2 }}
                                    disabled={!isDenomIndOrNsp}
                                    InputLabelProps={{ style: { fontSize: '0.875rem' } }}
                                />
                            </Grid>
                            <Grid item xs={4}>
                                <TextField
                                    type="number"
                                    label="Indéterminé"
                                    value={undeterminedCount || ""}
                                    inputProps={{ min: 0, style: { fontSize: '0.875rem' } }}
                                    onChange={(e) => setUndeterminedCount(parseInt(e.target.value))}
                                    fullWidth
                                    sx={{ marginTop: 2 }}
                                    InputLabelProps={{ style: { fontSize: '0.875rem' } }}
                                />
                            </Grid>
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Comportement</InputLabel>
                                    <Select
                                        value={observationData.comportement || ""}
                                        onChange={(e) => setObservationData({ ...observationData, comportement: e.target.value })}
                                        label="Comportement"
                                        variant="outlined"
                                        sx={{ width: '90%' }}
                                    >
                                        {comportementOptions.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            {isOrnitho && (
                                <Grid item xs={12}>
                                    <FormControl fullWidth>
                                        <InputLabel id="aves-label" style={{ fontSize: '0.875rem' }}>Indice nicheur</InputLabel>
                                        <Select
                                            labelId="aves-label"
                                            value={observationData.avescode || ''}
                                            onChange={(event) => {
                                                const selectedCode = event.target.value;
                                                const selectedItem = avesList.find(item => item.code === selectedCode);
                                                handleAvesChange(selectedItem);
                                            }}
                                            sx={{ width: '90%' }}
                                        >
                                            {avesList.map((item) => (
                                                <MenuItem key={item.code} value={item.code} style={{
                                                    fontSize: '0.875rem',
                                                    whiteSpace: 'normal', // Permet de retourner à la ligne
                                                    wordWrap: 'break-word', // Coupe les mots si nécessaire
                                                }}>
                                                    {item.libelle}
                                                </MenuItem>
                                            ))}
                                        </Select>

                                    </FormControl>
                                </Grid>
                            )}
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Statut biologique</InputLabel>
                                    <Select
                                        value={observationData.statutbio || ""}
                                        onChange={(e) => setObservationData({ ...observationData, statutbio: e.target.value })}
                                        label="Statut biologique"
                                        variant="outlined"
                                        sx={{ width: '90%' }}
                                    >
                                        {statutbioOptions.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Collecte</InputLabel>
                                    <Select
                                        value={observationData.collecte || ""}
                                        onChange={(e) => setObservationData({ ...observationData, collecte: e.target.value })}
                                        label="Collecte"
                                        variant="outlined"
                                        sx={{ width: '90%' }}
                                    >
                                        {collecteOptions.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <InputLabel style={{ fontSize: '0.875rem' }}>Protocole</InputLabel>
                                    <Select
                                        value={observationData.protocole || ""}
                                        onChange={(e) => setObservationData({ ...observationData, protocole: e.target.value })}
                                        label="Protocole"
                                        variant="outlined"
                                        sx={{ width: '90%' }}
                                    >
                                        {protocoleOptions.map((option, index) => (
                                            <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                {option.label}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={trouveMort === 1}
                                                onChange={(e) => setTrouveMort(e.target.checked ? 1 : 0)}
                                                color="primary"
                                            />
                                        }
                                        label={<Typography variant="body2">Trouvé mort</Typography>}
                                    />
                                    {trouveMort === 1 && (
                                        <Select
                                            value={observationData.mort || ""}
                                            onChange={(e) => setObservationData({ ...observationData, mort: e.target.value })}
                                            label="Cause de Mort"
                                            variant="outlined"
                                            fullWidth
                                            sx={{ width: '90%' }}
                                        >
                                            {mortOptions.map((option, index) => (
                                                <MenuItem key={index} value={option.value} style={{ fontSize: '0.875rem' }}>
                                                    {option.label}
                                                </MenuItem>
                                            ))}
                                        </Select>
                                    )}
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    label="Remarque"
                                    value={observationData.rqobs || ""}
                                    onChange={(e) => setObservationData({ ...observationData, rqobs: e.target.value })}
                                    fullWidth
                                    multiline
                                    rows={4}
                                    variant="outlined"
                                    InputProps={{ style: { fontSize: '0.875rem' } }}
                                    InputLabelProps={{ style: { fontSize: '0.875rem' } }}
                                />
                            </Grid>
                            <Grid item xs={12}>
                                <Typography variant="body2" sx={{ mb: 1, fontWeight: 500 }}>
                                    Photos ({photos.length}/5)
                                </Typography>
                                {photos.length > 0 && (
                                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 1 }}>
                                        {photos.map((photo, index) => (
                                            <Box key={index} sx={{ position: 'relative', width: 80, height: 80 }}>
                                                <img
                                                    src={photo}
                                                    alt={`photo-${index + 1}`}
                                                    style={{ width: 80, height: 80, objectFit: 'cover', borderRadius: 4 }}
                                                />
                                                <IconButton
                                                    size="small"
                                                    onClick={() => removePhoto(index)}
                                                    sx={{
                                                        position: 'absolute', top: -6, right: -6,
                                                        bgcolor: 'white', border: '1px solid #ccc',
                                                        padding: '2px', '&:hover': { bgcolor: '#fdd' }
                                                    }}
                                                >
                                                    <CloseIcon sx={{ fontSize: 14 }} />
                                                </IconButton>
                                            </Box>
                                        ))}
                                    </Box>
                                )}
                                {photos.length < 5 && (
                                    <Box sx={{ display: 'flex', gap: 1 }}>
                                        <Button
                                            variant="outlined"
                                            size="small"
                                            startIcon={<CameraAltIcon />}
                                            component="label"
                                        >
                                            Appareil photo
                                            <input
                                                type="file"
                                                accept="image/*"
                                                capture="environment"
                                                hidden
                                                onChange={handlePhotoCapture}
                                            />
                                        </Button>
                                        <Button
                                            variant="outlined"
                                            size="small"
                                            startIcon={<PhotoLibraryIcon />}
                                            component="label"
                                        >
                                            Galerie
                                            <input
                                                type="file"
                                                accept="image/*"
                                                multiple
                                                hidden
                                                onChange={handlePhotoCapture}
                                            />
                                        </Button>
                                    </Box>
                                )}
                            </Grid>
                        </>
                    )}
                    <Grid item xs={12}>

                        <Box
                            sx={{
                                position: 'fixed',
                                bottom: 100,
                                right: 16,
                                zIndex: 1000,
                            }}
                        >
                            <Fab color="red" aria-label="fiche" onClick={onCancel} variant="extended">
                                Retour fiche
                            </Fab>
                            {formData.especes && Object.keys(formData.especes).length > 0 && (
                                <Fab color="secondary" aria-label="annuler" onClick={onSynthese} variant="extended">
                                    Annuler
                                </Fab>
                            )}
                            <Fab color="primary" aria-label="save" onClick={handleSubmit} variant="extended">
                                Enregister
                            </Fab>
                        </Box>
                    </Grid>
                </Grid>
            </Card>
        </Box>
    );
};

export default ObservationForm;
