import React, { useContext, useState, useEffect } from 'react';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardActions from '@mui/material/CardActions';
import Button from '@mui/material/Button';
import SyncIcon from '@mui/icons-material/Sync';
import Typography from '@mui/material/Typography';
import { MainContext } from '../context/MainContext';
import { db } from '../db/db';
import InfoIcon from '@mui/icons-material/Info';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, Fab } from '@mui/material';
import { Navigate } from 'react-router-dom';
import { useNavigate } from 'react-router-dom';

export default function Synchro() {
    const { obsCount, setObsCount } = useContext(MainContext);
    const [syncing, setSyncing] = useState(false);
    const [syncError, setSyncError] = useState(null);
    const [syncSuccess, setSyncSuccess] = useState(false);
    const [openDial, setOpenDial] = useState(false);
    const [photoDetCount, setPhotoDetCount] = useState(0);
    const navigate = useNavigate();
    const apiBaseUrl = process.env.REACT_APP_API_BASE_URL;

    // Récupération du nombre de photos à synchroniser dès le chargement
    useEffect(() => {
        const fetchPhotoDetCount = async () => {
            const count = await db.photodet.count();
            setPhotoDetCount(count);
        };
        fetchPhotoDetCount();
    }, []);

    // Synchronisation des tables classiques (fiche, obs, ligne, user)
    const syncData = async () => {
        setSyncing(true);
        setSyncError(null);
        setSyncSuccess(false);

        try {
            const fiches = await db.fiche.toArray();
            const obs = await db.obs.toArray();
            const lignes = await db.ligne.toArray();
            const users = await db.user.toArray();
            const obsPhotos = await db.obsphoto.toArray();

            // Attacher les photos à leur observation respective
            const obsWithPhotos = obs.map((o) => ({
                ...o,
                photos: obsPhotos.filter((p) => p.idobs === o.id).map((p) => p.photo),
            }));

            const dataToSync = {
                fiches,
                obs: obsWithPhotos,
                lignes,
                users
            };

            console.log('Data to sync:', dataToSync);

            const response = await fetch(`${apiBaseUrl}/api/v1/sync`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(dataToSync)
            });

            if (!response.ok) {
                const errorData = await response.json();
                const errorMessage = errorData.message || 'Erreur inconnue';
                const errorDetails = errorData.error;
                console.error('Détails de l\'erreur:', errorDetails);
                throw new Error(`${ errorMessage }: ${ errorDetails }`);
            }

            const result = await response.json();
            console.log('Données synchronisées avec succès:', result);

            await db.fiche.clear();
            await db.obs.clear();
            await db.ligne.clear();
            await db.obsphoto.clear();
            setSyncSuccess(true);
        } catch (error) {
            console.error('Erreur lors de la synchronisation des données:', error);

            // error.message contient désormais les détails
            setSyncError(error.message);
        } finally {
            setSyncing(false); // Terminer l'état de synchronisation

        }
        setObsCount(0); // Réinitialiser le compteur d'observations
        navigate('/'); // Rediriger vers la page d'accueil
    };

    // Synchronisation des photos de la table photodet
    const syncPhotodetData = async () => {
        try {
            const deter = await db.photodet.toArray();
            const users = await db.user.toArray();

            const response = await fetch('https://www.lannobs.langazel.asso.fr/api/v1/deter', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ deter, users })
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(`${ errorData.message || 'Erreur inconnue' }: ${ errorData.error }`);
            }

            await db.photodet.clear();
            setPhotoDetCount(0);
        } catch (error) {
            console.error('Erreur lors de la synchronisation des données:', error);

            // error.message contient désormais les détails
            setSyncError(error.message);
        } finally {
            setSyncing(false); // Terminer l'état de synchronisation

        }
    };

    // synchro tout
    const handleFullSync = async () => {
        setSyncing(true);
        setSyncError(null);
        setSyncSuccess(false);

        try {
            await syncData();
            await syncPhotodetData();
            setSyncSuccess(true);
        } catch (error) {
            console.error('Erreur pendant la synchro complète:', error);
            setSyncError(error.message);
        } finally {
            setSyncing(false);
            navigate('/');
        }
    };

    // Fonction pour ouvrir le dialogue
    const handleOpenDialog = () => {
        setOpenDial(true);
    };

    // Fonction pour fermer le dialogue
    const handleCloseDialog = () => {
        setOpenDial(false);
    };

    return (
        <box style={{ display: 'flex', justifyContent: 'center', marginTop: 4, height: '80vh' }}>
            <Fab size="small" color="jaune" aria-label="help" onClick={handleOpenDialog}
                style={{ position: 'fixed', bottom: 100, left: 16 }}>
                <HelpOutlineIcon />
            </Fab>
            {/* Dialogue pour afficher les conseils */}
            <Dialog open={openDial} onClose={handleCloseDialog}>
                <DialogTitle>Conseils d'utilisation</DialogTitle>
                <DialogContent>
                    <p>Assurez vous d'avoir du réseau ou d'etre connecté en wifi avant de synchroniser</p>
                    <p>Synchroniser les données les suppriment de votre téléphone</p>
                    <p>Mais rassurez vous, elles sont transférées sur la base de données principale</p>
                    <p>Pour revenir sur la page d'accueil, cliquer sur lannObs'go en haut à gauche</p>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleCloseDialog}>Fermer</Button>
                </DialogActions>
            </Dialog >
            {syncing ? (
                <CircularProgress size={60} color="primary" /> // Indicateur de chargement
            ) : (
                <Card sx={{ width: '85vw', height: '50vh', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
                    <CardContent sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%' }}>
                        <SyncIcon style={{ fontSize: 60, color: '#0e86a1' }} />
                        <Typography variant="h5" component="div">
                            Synchronisation
                        </Typography>
                        <Typography variant="body2" color="textSecondary">
                            Observations à synchroniser : {obsCount}
                        </Typography>
                        <Typography variant="body2" color="textSecondary">
                            Détermination à synchroniser : {photoDetCount}
                        </Typography>
                    </CardContent>
                    <CardActions sx={{ flexDirection: 'column', gap: 1, paddingX: 2, paddingBottom: 2 }}>
                        <Button
                            onClick={handleFullSync}
                            variant="contained"
                            color="primary"
                            fullWidth
                            size="large"
                            sx={{ fontWeight: 'bold', fontSize: '1rem' }}
                        >
                            {syncing ? 'Synchronisation...' : 'Tout synchroniser'}
                        </Button>

                        <Button onClick={syncData} variant="outlined" color="primary" fullWidth>
                            {syncing ? '...' : 'Synchroniser seulement les données'}
                        </Button>

                        <Button onClick={syncPhotodetData} variant="outlined" color="secondary" fullWidth>
                            {syncing ? '...' : 'Synchroniser les demandes de détermination'}
                        </Button>
                    </CardActions>
                    {syncSuccess && <Typography variant="body2" color="green">Synchronisation réussie!</Typography>}
                    {syncError && <Typography variant="body2" color="red">Erreur : {syncError}</Typography>}
                </Card>
            )}
        </box>
    );
}
