import React, { useState, useEffect, useContext } from 'react';
import { Container, Card, CardContent, Button, Typography, CircularProgress, Box, CardHeader, Fab, Chip } from '@mui/material';
import { db } from '../db/db';
import { useNavigate } from 'react-router-dom';
import { MainContext } from '../context/MainContext';
import SyncIcon from '@mui/icons-material/Sync';
import { use } from 'react';

export default function Parametre() {
    const { fetchUser, handleUpdateAll, handleUpdateCommuneData,
        handleUpdateObservatoireApiData, handleUpdateSpeciesData, handleUpdateParamData, handleUpdateSiteData,
        setStatus, fetchCounts, observatoireCount, speciesCount, communeCount, siteCount, loading, setLoading,
        observateurs, observateursCount,
    } = useContext(MainContext);

    const navigate = useNavigate();

    //Vider le user
    async function handleClearDbUser() {
        try {
            await db.user.clear();
            setStatus('Base de données des utilisateurs vidée');
            navigate('/');
        } catch (error) {
            setStatus(`Échec du vidage de la base de données: ${error}`);
        }
        fetchUser();
    }

    useEffect(() => {
        console.log(`Loading a changé : ${loading}`);
    }, [loading]);

    return (
        <Box>
            {loading ? (
                <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
                    <CircularProgress />
                </Box>
            ) : (
                <>
                    <Box
                        sx={{
                            display: 'row',
                            justifyContent: 'center',
                            alignItems: 'center',
                            width: '100vw',
                            background: 'linear-gradient(135deg, #cce0dc, #ebfffd)',
                            paddingTop: 2,
                            paddingBottom: 16,
                        }}
                    >
                        <Card sx={{ marginBottom: 1 }}>
                            <CardHeader
                                title="Si c'est votre première connexion, mettez à jour les référentiels"
                                subheader="Il est prudent de remettre à jour régulièrement les référentiels pour être en phase avec la base de données"
                            />

                            <CardContent>
                                <Button variant="contained" onClick={handleUpdateAll} color="secondary">
                                    Tout mettre à jour
                                </Button>
                            </CardContent>
                        </Card>
                        <Card sx={{ marginBottom: 1 }}>
                            <CardContent>
                                <Typography variant="h5">Observatoires</Typography>
                                <Button onClick={handleUpdateObservatoireApiData} size="small">Mettre à jour les données des observatoires</Button>
                                <Typography variant="body1">Nombre d'observatoires : {observatoireCount}</Typography>
                            </CardContent>
                        </Card>
                        <Card sx={{ marginBottom: 1 }}>
                            <CardContent>
                                <Typography variant="h5">Espèces</Typography>
                                <Button onClick={handleUpdateSpeciesData} size="small">Mettre à jour la liste des espèces</Button>
                                <Typography variant="body1">Nombre d'espèces : {speciesCount}</Typography>
                            </CardContent>
                        </Card>
                        <Card sx={{ marginBottom: 1 }}>
                            <CardContent>
                                <Typography variant="h5">Paramètres</Typography>
                                <Typography variant="caption">(Etudes, protocoles, stades, etc)</Typography>
                                <Button onClick={handleUpdateParamData} size="small">Mettre à jour les paramètres</Button>
                            </CardContent>
                        </Card>
                        <Card sx={{ marginBottom: 1 }}>
                            <CardContent>
                                <Typography variant="h5">Communes</Typography>
                                <Button onClick={handleUpdateCommuneData} size="small">Mettre à jour les communes</Button>
                                <Typography variant="body1">Nombre de communes : {communeCount}</Typography>
                            </CardContent>
                        </Card>
                        <Card sx={{ marginBottom: 1 }}>
                            <CardContent>
                                <Typography variant="h5">Sites et observateurs</Typography>
                                <Button onClick={handleUpdateSiteData} size="small">Mettre à jour les sites</Button>
                                <Typography variant="body1">Nombre de sites : {siteCount}</Typography>
                                <Typography variant="body1">Nombre d'observateurs : {observateursCount}</Typography>
                            </CardContent>
                        </Card>

                        <Chip
                            label="Changer d'utilisateur"
                            onClick={handleClearDbUser}
                            onDelete={handleClearDbUser}
                            deleteIcon={<SyncIcon />}
                            color="success"
                        />
                    </Box>
                </>
            )}

        </Box>
    );
};

