import React, { useContext, useState, useEffect } from 'react';
import {
  Container, Button, Box, Chip, Snackbar, Badge, IconButton, DialogTitle,
  DialogContent, DialogContentText, Dialog, DialogActions, Fab,
  Alert,
  CircularProgress,
  Stack,
  Card
} from '@mui/material';
import Grid from '@mui/material/Grid';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import { MainContext } from '../context/MainContext';
import { db } from '../db/db';
import LoginForm from './LoginForm';
import { Link, useNavigate } from 'react-router-dom';
import DeleteIcon from '@mui/icons-material/Delete';
import CheckIcon from '@mui/icons-material/Check';
import SyncProblemIcon from '@mui/icons-material/SyncProblem';
import SyncIcon from '@mui/icons-material/Sync';
import VisibilityIcon from '@mui/icons-material/Visibility';
import SettingsIcon from '@mui/icons-material/Settings';
import CloseIcon from '@mui/icons-material/Close';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { Sync } from '@mui/icons-material';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import LiveHelpIcon from '@mui/icons-material/LiveHelp';
import { useTheme } from '@mui/material/styles';
import { SpeedDial, SpeedDialAction, SpeedDialIcon } from '@mui/material';
import AddIcon from '@mui/icons-material/Add';

export default function Home() {
  const { user, fetchUser, obsCount, setObsCount,
    checkDbData, loadingObs, handleUpdateAll, setPhase, allParam, setAllParam,
    formData, ssoLoading } = useContext(MainContext);
  const [status, setStatus] = useState('');
  const navigate = useNavigate();
  const [openDialog, setOpenDialog] = useState(false);
  const [showSnackbar, setShowSnackbar] = useState(false);
  const [open, setOpen] = useState(false);
  const [version, setVersion] = useState(null); // Version récupérée via l'API
  const [isUpToDate, setIsUpToDate] = useState(false); // Indique si la version est à jour
  const [statusCharg, setStatusCharg] = useState('Chargement de la version...'); // Statut de l'opération
  const [loading, setLoading] = useState(false); // State to manage loading
  const [isParamUpdate, setIsParamUpdate] = useState(true); // Indique si les paramètres sont à jour
  const theme = useTheme();
  const apiBaseUrl = process.env.REACT_APP_API_BASE_URL;
  const [openUpdateDialog, setOpenUpdateDialog] = useState(false);

  useEffect(() => {
    fetchUser();
    console.log("loading", loadingObs);
    const fetchObsCount = async () => {
      try {
        const count = await db.obs.count();
        setObsCount(count);
      } catch (error) {
        console.error('Erreur lors de la récupération du nombre de lignes dans obs:', error);
      }
    };
    fetchObsCount();
  }, []);

  //vider les obs
  async function handleClearObs() {
    try {
      await db.obs.clear();
      await db.fiche.clear();
      await db.ligne.clear();
      setStatus('Base de données des utilisateurs vidée');

    } catch (error) {
      setStatus(`Échec du vidage de la base de données: ${error}`);
    }
    fetchUser();
  }

  //Vider les parametres
  async function handleClearParam() {
    try {
      await db.species.clear();
      await db.observatoire.clear();
      await db.etude.clear();
      await db.protocole.clear();
      await db.orga.clear();
      await db.comportement.clear();
      await db.methode.clear();
      await db.occstatutbio.clear();
      await db.occtype.clear();
      await db.prospection.clear();
      await db.stade.clear();
      await db.site.clear();
      await db.observateurs.clear();
      await db.commune.clear();

      setStatus('Base de données des utilisateurs vidée');

    } catch (error) {
      setStatus(`Échec du vidage de la base de données: ${error}`);
    }
    fetchUser();
  }

  //pour déclencher le controle des tables DB dexie
  useEffect(() => {

    const verifyTables = async () => {
      const result = await checkDbData();
      setAllParam(result);
    };
    verifyTables();

    const checkForOldEntries = async () => {
      const hasOldEntries = await checkOldEntries();
      setShowSnackbar(hasOldEntries);
    };
    checkForOldEntries();


  }, []);

  //pour récupérer la date du jour au bon format
  function getTodayDate() {
    const today = new Date();
    const dd = String(today.getDate()).padStart(2, '0'); // Jour du mois avec zéro en tête
    const mm = String(today.getMonth() + 1).padStart(2, '0'); // Mois (commence à 0) avec zéro en tête
    const yyyy = today.getFullYear(); // Année
    return `${yyyy}-${mm}-${dd}`;
  }

  //Vérifier si il y a des obs qui ont plus d'une journée
  async function checkOldEntries() {
    const today = getTodayDate();
    const oldEntries = await db.fiche.where('datesaisie').below(today).toArray();
    return oldEntries.length > 0;
  }

  //Pour naviguer vers la saisie en vérifiant que les parametres sont biens chargés
  const handleAddObservation = () => {
    if (allParam === 'non') {
      setOpenDialog(true);
    } else {
      setPhase('map');
      navigate('/saisi');
    }
  };

  //pour fermer la snack d'alerte de synchro
  const handleSnackbarClose = () => {
    setShowSnackbar(false);
  };

  //La snackbar de rappel de synchro
  const actionSnack = (
    <>
      <Button color="secondary" size="small" onClick={handleSnackbarClose}>
        ok
      </Button>
      <IconButton size="small" aria-label="close" color="inherit" onClick={handleSnackbarClose}>
        <CloseIcon fontSize="small" />
      </IconButton>
    </>
  );

  // Fonction pour ouvrir le dialogue
  const handleOpenDialog = () => {
    setOpen(true);
  };

  // Fonction pour fermer le dialogue
  const handleCloseDialog = () => {
    setOpen(false);
  };


  //fonction d'appel a l'api pour récupérer la version en cours

  async function recupVersion() {
    try {
      const response = await fetch(`${apiBaseUrl}/api/v1/version`);
      const data = await response.json();
      if (data.version) {
        setVersion(data.version); // Met à jour l'état
        return data.version; // Retourne la version
      } else {
        throw new Error('Clé "version" manquante dans la réponse');
      }
    } catch (error) {
      console.error('Erreur lors de la récupération de la version', error);
      throw error;
    }
  }

  // useEffect pour déclencher la récupération de la version à chaque chargement de la page
  useEffect(() => {
    async function fetchAndCompareVersion() {
      try {
        const fetchedVersion = await recupVersion(); // Attendre que la version soit récupérée
        console.log('Version récupérée:', fetchedVersion);
        console.log('Version de l\'application:', process.env.REACT_APP_VERSION);
        if (process.env.REACT_APP_VERSION) {
          const isUpToDate = fetchedVersion && fetchedVersion === process.env.REACT_APP_VERSION;
          setIsUpToDate(isUpToDate);

          // Si la version n'est pas à jour, ouvrir le dialogue
          if (!isUpToDate) {
            console.log('Version de l\'application:', process.env.REACT_APP_VERSION);
            setOpenUpdateDialog(true); // Ouvre le dialogue
          }
        }
      } catch (error) {
        console.error('Erreur lors de la récupération de la version', error);
        setStatus(`Erreur : ${error.message}`);
      }
    }

    fetchAndCompareVersion();
  }, []);

  //fonction pour recharger la page
  const handlereload = async () => {
    setLoading(true);
    await handleUpdateAll();
    window.location.reload();
  };
  // Fonction pour fermer le dialogue
  const handleCloseUpdateDialog = () => {
    setOpenUpdateDialog(false); // Ferme le dialogue
  };

  // Fonction pour ouvrir le dialogue
  const handleOpenDeter = () => {
    navigate('/deter');
    setPhase('');
  };

  const actions = [
    { icon: <AddCircleOutlineIcon sx={{ fontSize: 30 }} />, name: 'Saisir une observation', onClick: handleAddObservation },
    { icon: <LiveHelpIcon sx={{ fontSize: 30 }} />, name: 'Demande de détermination', onClick: handleOpenDeter },
  ];

  //pour déclencher le controle des tables DB dexie
  useEffect(() => {
    setAllParam('oui');
    const verifyTables = async () => {
      const result = await checkDbData();
      setAllParam(result);
    };
    console.log('allparam', allParam);
    verifyTables();
  }, []);

  return (
    <Box    >
      {loading || ssoLoading ? (
        <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
          <CircularProgress />
        </Box>
      ) : !user ? (
        <LoginForm />
      ) : (
        <>
          <Snackbar
            open={showSnackbar}
            autoHideDuration={6000}
            onClose={handleSnackbarClose}
            message="Vous avez des obs à synchroniser."
            action={actionSnack}
            anchorOrigin={{ vertical: 'center', horizontal: 'center' }}

          />
          {/* FAB aide */}
          <Fab size="small" aria-label="help" onClick={handleOpenDialog}
            style={{ position: 'fixed', bottom: 100, left: 16 }}>
            <HelpOutlineIcon />
          </Fab>

          {/* FAB ajout obs ou deter */}
          <SpeedDial
            ariaLabel="FAB avec options"
            sx={{
              position: 'fixed', bottom: 100, left: '50%',
              transform: 'translateX(-50%)', zIndex: 10
            }}
            icon={<SpeedDialIcon openIcon={<AddIcon />} />}
          >
            {actions.map((action) => (
              <SpeedDialAction
                key={action.name}
                icon={action.icon} tooltipTitle={action.name}
                tooltipOpen
                onClick={action.onClick}
                sx={{ marginBottom: 1 }}
              />
            ))}
          </SpeedDial>

          {/* Dialogue pour afficher les conseils */}
          <Dialog open={open} onClose={handleCloseDialog}>
            <DialogTitle>Conseils d'utilisation</DialogTitle>
            <DialogContent>
              <p><SettingsIcon /> Pour mettre à jour les paramètres d'utilisation, à utiliser régulièrement </p>
              <p><SyncIcon /> : Pour envoyer vos données sur la base. A faire dès que possible quand vous avez fini de saisir vos obs</p>
              <p><VisibilityIcon />Indique combien d'obs vous avez saisi dans le petit badge et vous permet de voir vos obs et de les modifier</p>
              <p> Vous pouvez changer d'utilisateur dans le menu paramètres.</p>
              <p> Mais attention, c'est l'utilisateur connecté qui sera l'observateur des données synchronisées</p>
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseDialog}>Fermer</Button>
            </DialogActions>
          </Dialog>


          <Box
            sx={{
              minHeight: 'calc(90vh)', // ajuste selon la hauteur de la bottom nav + FAB
              minWidth: '80vw',
              backgroundImage: `url(${process.env.PUBLIC_URL + '/images/lannobsgo-bg.png.jpg'})`,
              backgroundSize: 'cover',
              backgroundPosition: 'top',
              backgroundRepeat: 'no-repeat',
              color: '#fff',
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'flex-start',
              alignItems: 'center',
              marginTop: 2,
              padding: 2,

            }}
          >
            <Typography variant="h4" >
              Bonjour, {user.prenom} {user.nom}
            </Typography>
            {/* affichage d'un encart si jamais des obs sont en cours de saisi  */}
            {formData.especes && Object.keys(formData.especes).length > 0 ? (
              <Box
                sx={{
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  marginTop: 2,
                }}
              >
                <Card
                  sx={{
                    width: '100%',
                    padding: 1,
                    backgroundColor: 'rgba(255, 255, 255, 0.9)',
                    borderRadius: 2,
                  }}
                >
                  <Typography variant="h6" align="center" gutterBottom>
                    Vous avez des obs' en cours de saisie
                  </Typography>
                  <Typography variant="body1" align="center">
                    Pensez à les valider avant de continuer.
                  </Typography>

                  <Typography variant="body2" align="center" sx={{ marginTop: 2 }}>
                    <Link
                      onClick={(event) => {
                        event.preventDefault();
                        setPhase('synthese');
                        navigate('/saisi');
                      }}
                      sx={{
                        textDecoration: 'none',
                        color: 'primary.main',
                        fontWeight: 'bold',
                        '&:hover': { textDecoration: 'underline' },
                      }}
                    >
                      Reprendre la saisie de vos espèces
                    </Link>
                  </Typography>

                </Card>
              </Box>
            )
              : null}
          
            <Box>
              <Dialog
                open={openUpdateDialog}
                onClose={handleCloseDialog}
                aria-labelledby="update-dialog-title"
                aria-describedby="update-dialog-description"
              >
                <DialogTitle id="update-dialog-title">Mise à jour disponible</DialogTitle>
                <DialogContent>
                  <DialogContentText id="update-dialog-description">
                    Une mise à jour est disponible. Recharger l'application pour appliquer les dernières modifications
                  </DialogContentText>
                </DialogContent>
                <DialogActions>
                  <Button onClick={handlereload} color="primary" autoFocus>
                    Recharger
                  </Button>
                </DialogActions>
              </Dialog>
            </Box>
          </Box>
          {/* Dev tools */}
          {user.droits >= 3 && (
            <Box
              sx={{
                border: '1px solid', borderColor: 'grey.400', borderRadius: 2, padding: 2, position: 'relative', marginTop: 3,
              }}
            >
              <Typography
                variant="subtitle1"
                sx={{ position: 'absolute', top: '-10px', left: '16px', padding: '0 8px' }}
              >
                Outils de développement
              </Typography>
              <Grid container spacing={2}>

                <Grid item xs={12} sm={6} md={4}>
                  <Chip
                    label="Effacer les Obs"
                    onClick={handleClearObs}
                    onDelete={handleClearObs}
                    deleteIcon={<DeleteIcon />}
                    color="error"
                  />
                </Grid>
                <Grid item xs={12} sm={6} md={4}>
                  <Chip
                    label="Effacer les paramètres"
                    onClick={handleClearParam}
                    onDelete={handleClearParam}
                    deleteIcon={<DeleteIcon />}
                    color="error"
                  />
                </Grid>
              </Grid>
            </Box>
          )}
          <Dialog
            open={openDialog}
            onClose={() => setOpenDialog(false)}
          >
            <DialogTitle>Paramètres manquants</DialogTitle>
            <DialogContent>
              <DialogContentText>
                Veuillez mettre à jour les paramètres avant de procéder à la saisie.
              </DialogContentText>
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setOpenDialog(false)}>Annuler</Button>
              <Button onClick={() => navigate('/parametre')} autoFocus>
                Mettre à jour
              </Button>
            </DialogActions>
          </Dialog>

          {/* Footer */}
          <Box sx={{ textAlign: 'center', marginTop: 4 }}>
            <Typography variant="body2" sx={{ color: '#7f8c8d' }}>
              © 2026 LannObs'Go. Tous droits réservés.
            </Typography>
          </Box>
        </>
      )}
    </Box>
  );
}
