import React, { useContext, useState, useEffect } from 'react';
import {
  BottomNavigation,
  BottomNavigationAction,
  Paper,
  Box,
  Typography,
  Fab,
  Badge
} from '@mui/material';

import HomeIcon from '@mui/icons-material/Home';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import ListAltIcon from '@mui/icons-material/ListAlt';
import SettingsIcon from '@mui/icons-material/Settings';
import AddIcon from '@mui/icons-material/Add';
import { MainContext } from '../context/MainContext';
import VisibilityIcon from '@mui/icons-material/Visibility';
import { db } from '../db/db';

export default function Home() {
  const { user, fetchUser, obsCount, setObsCount,
    checkDbData, loadingObs, handleUpdateAll } = useContext(MainContext);
  const [value, setValue] = useState(0);
  const [allParam, setAllParam] = useState('Non');

  const renderContent = () => {
    const contentStyle = {
      display: 'flex',
      justifyContent: 'center',
      marginTop: 2, // Réduisez la marge supérieure
      padding: 2,   // Ajoutez un peu de padding si nécessaire
    };
    switch (value) {
      case 0:
        return (
          <Box sx={{ ...contentStyle, flexDirection: 'column', alignItems: 'center' }}>
            <Typography variant="h5" align="center">Bienvenue sur LannObs'Go 🌿</Typography>
            <Typography variant="subtitle1" align="center">
              {user ? `${user.prenom} ${user.nom}` : ''}
            </Typography>
          </Box>
        );
      case 1:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">Aide à la Détermination</Typography>
          </Box>
        );
      case 2:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">Mes Observations</Typography>
          </Box>
        );
      case 3:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">Paramètres</Typography>
          </Box>
        );
      default:
        return null;
    }
  };

  const handleAddObservation = () => {
    alert('Redirection vers création d’observation'); // à remplacer par navigation réelle
  };

  //pour déclencher le compte des obs
  useEffect(() => {
    fetchUser();
    const fetchObsCount = async () => {
      try {
        const count = await db.obs.count();
        setObsCount(count);
      } catch (error) {
        console.error('Erreur lors de la récupération du nombre de lignes dans obs:', error);
      }
    };
    fetchObsCount();
  }, []);

  //pour déclencher le controle des tables DB dexie
  useEffect(() => {

    const verifyTables = async () => {
      const result = await checkDbData();
      setAllParam(result);
    };
    verifyTables();
  }, []);

  return (
    <Box >
      <Box
        sx={{
          minHeight: 'calc(100vh)', // ajuste selon la hauteur de la bottom nav + FAB
          backgroundImage: `url(${process.env.PUBLIC_URL + '/images/lannobsgo-bg.png.jpg'})`,
          backgroundSize: 'cover',
          backgroundPosition: 'top',
          backgroundRepeat: 'no-repeat',
          color: '#fff',
          textShadow: '0 1px 4px rgba(0,0,0,0.7)'

        }}
      >
        {renderContent()}
      </Box>

      {/* FAB au centre */}
      <Fab
        color="primary"
        aria-label="add"
        onClick={handleAddObservation}
        sx={{
          position: 'fixed',
          bottom: 70,
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 10
        }}
      >
        <AddIcon />
      </Fab>

      {/* Bottom Navigation */}
      <Paper
        sx={{
          position: 'fixed',
          bottom: 0,
          left: 0,
          right: 0,
          borderTop: '1px solid #ccc',
        }}
        elevation={3}
      >
        <BottomNavigation
          showLabels
          value={value}
          onChange={(event, newValue) => {
            setValue(newValue);
          }}
        >
          <BottomNavigationAction label="Accueil" icon={<HomeIcon />} />
          <BottomNavigationAction label="Détermination" icon={<HelpOutlineIcon />} />
          <BottomNavigationAction
            label="Observations"
            icon={
              <Badge badgeContent={obsCount} >
                <VisibilityIcon />
              </Badge>
            }
          />
          <BottomNavigationAction
            label="Paramètres"
            icon={
              <Badge color="error" variant="dot" invisible={allParam === 'Oui'}>
                <SettingsIcon />
              </Badge>
            }
          />
        </BottomNavigation>
      </Paper>
    </Box>
  );
}
