import React, { useContext, useState, useEffect } from 'react';
import { Card, TextField, FormControl, InputLabel, Select, MenuItem, Button, Box, Typography, Switch, IconButton, Grid, Fab, DialogContent, Dialog, DialogTitle, DialogActions, ListItem, ListItemIcon, ListItemText, Checkbox, List } from '@mui/material';
import { MainContext } from '../context/MainContext';
import InfoIcon from '@mui/icons-material/Info';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { db } from '../db/db';



const FicheForm = ({ organismes, etudes, onCancel }) => {
    const { formData, setFormData, updatePhase, setPhase, updateFormData, clickedPosition, selectedSite } = useContext(MainContext);
    const [open, setOpen] = useState(false);
    const [observateurs, setObservateurs] = useState([]); // List of all observateurs
    const [selectedObservateurs, setSelectedObservateurs] = useState([]); // Selected items
    const [unselectedObservateurs, setUnselectedObservateurs] = useState([]); // Unselected items
    const [openObsDialog, setOpenObsDialog] = useState(false);
    const [left, setLeft] = useState([]); // non sélectionnés
    const [right, setRight] = useState([]); // sélectionnés
    const [selectedObservateursNames, setSelectedObservateursNames] = useState([]); // New state for selected names

    //Mise a jour a la validation
    const handleSubmit = (event) => {
        event.preventDefault();
        // Mettre à jour les données de la fiche dans le contexte
        const newFormData = {
            fiche: {
                site: selectedSite?.site || null,
                idsite: selectedSite?.idsite || null,
                newsite: selectedSite?.newsite || false,
                idcoord: selectedSite?.idcoord || null,
                lat: clickedPosition.lat,
                long: clickedPosition.lng,
                date1: formData.fiche.date,
                date2: formData.fiche.date2,
                organisme: formData.fiche.organisme,
                etude: formData.fiche.etude,
                typeDonnee: formData.fiche.typeDonnee,
                diffusion: formData.fiche.diffusion,
                plusobser: right.map((o) => o.idobser),
            }
        };
        updateFormData(newFormData);
        setPhase('observation');
    };

    // Fonction pour ouvrir le dialogue
    const handleOpenDialog = () => {
        setOpen(true);
    };

    // Fonction pour fermer le dialogue
    const handleCloseDialog = () => {
        setOpen(false);
    };
    //pour charger les observateurs
    useEffect(() => {
        const fetchObservateurs = async () => {
            try {
                const [currentUser] = await db.user.limit(1).toArray();
                const allObservateurs = await db.observateurs.toArray();

                // Filtrer pour enlever l'utilisateur connecté (par idobser)
                const filtered = allObservateurs.filter(o => o.idobser !== currentUser.idobser);

                // Trier par nom
                const sortedObservateurs = filtered.sort((a, b) => a.nom.localeCompare(b.nom));

                setLeft(sortedObservateurs); // Tous non sélectionnés par défaut
            } catch (error) {
                console.error('Erreur lors du chargement des observateurs:', error);
            }
        };
        fetchObservateurs();
    }, []);


    const handleToggleObservateur = (item) => {
        if (right.includes(item)) {
            setRight(right.filter(i => i !== item));
            setLeft([...left, item]);
        } else {
            setRight([...right, item]);
            setLeft(left.filter(i => i !== item));
        }
        // Update the selected names as a comma-separated string
        const updatedRight = right.includes(item)
            ? right.filter((i) => i !== item)
            : [...right, item];
        const names = updatedRight.map((obs) => obs.nom).join(', '); // Extract 'nom' and join with commas
        setSelectedObservateursNames(names);
    };

    return (
        <Box sx={{justifyContent: 'center', alignItems: 'center', height: '100vh',
            background: 'linear-gradient(135deg, #cce0dc, #ebfffd)', paddingTop: 1,
        }}>
            <Card sx={{ padding: 1 }}>
                {/* Bouton pour ouvrir le dialogue */}
                <Fab size="small" color="jaune"  aria-label="help" onClick={handleOpenDialog} 
                style={{ position: 'fixed', bottom: 90, left: 16 }}>
                    <HelpOutlineIcon />
                </Fab>

                {/* Dialogue pour afficher les conseils */}
                <Dialog open={open} onClose={handleCloseDialog}>
                    <DialogTitle>Conseils d'utilisation</DialogTitle>
                    <DialogContent>
                        <p>Vous n'etes pas obligé de mettre un date de fin. Privilégier toujours une seule date précise</p>
                        <p>Ne sélectionnez une étude que si vous réalisez des relevés protocolés en lien avec une étude</p>
                        <p>Privées : ne contriburons pas à alimenter les bases autres que Langazel</p>
                        <p>Diffusion : permet de flouter la réstitution des données</p>
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={handleCloseDialog}>Fermer</Button>
                    </DialogActions>
                </Dialog>

                {/* Dialogue pour afficher les co_obs */}
                <Dialog open={openObsDialog} onClose={() => setOpenObsDialog(false)} fullWidth maxWidth="md">
                    <DialogTitle>Co-observateurs</DialogTitle>
                    <DialogContent>
                        <Grid
                            container
                            spacing={1}
                            justifyContent="center"
                            alignItems="flex-start" // ⬅️ Alignement haut
                        >
                            <Grid item xs={5.5}>
                                <Typography>Disponible</Typography>
                                <List dense sx={{ maxHeight: '80%', overflow: 'auto' }}>
                                    {left.map((item) => (
                                        <ListItem key={item.id} button onClick={() => handleToggleObservateur(item)}>
                                            <ListItemText primary={item.observateur} />
                                        </ListItem>
                                    ))}
                                </List>
                            </Grid>
                            <Grid item xs={1} style={{ textAlign: 'center', paddingTop: '40px' }}>
                                <Typography>⇄</Typography>
                            </Grid>
                            <Grid item xs={5.5} sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                                <Typography>Sélectionnés</Typography>
                                <List dense sx={{ maxHeight: 300, overflow: 'auto' }}>
                                    {right.map((item) => (
                                        <ListItem key={item.id} button onClick={() => handleToggleObservateur(item)}>
                                            <ListItemText primary={item.observateur} />
                                        </ListItem>
                                    ))}
                                </List>
                            </Grid>
                        </Grid>
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={() => setOpenObsDialog(false)}>Annuler</Button>
                        <Button onClick={() => {
                            // Enregistrer dans formData
                            setFormData(prev => ({
                                ...prev,
                                fiche: { ...prev.fiche, observateurs: right.map(o => o.id) }
                            }));
                            setOpenObsDialog(false);
                        }}>
                            Enregistrer
                        </Button>
                    </DialogActions>
                </Dialog>

                <Typography variant="h5">Fiche d'observation</Typography>
                {
                    clickedPosition && (
                        <Typography>
                            {selectedSite?.site ? `${selectedSite.site} : ` : ""}
                            {clickedPosition.lat && clickedPosition.lng ? `${clickedPosition.lat.toFixed(4)}, ${clickedPosition.lng.toFixed(4)}` : ""}
                        </Typography>
                    )
                }

                <form onSubmit={handleSubmit}>
                    <Grid container spacing={2} direction="row" justifyContent="center" alignItems="center">
                        <Grid item xs={6}>
                            <TextField
                                label="Date de début"
                                type="date"
                                value={formData.fiche.date}
                                onChange={(e) => setFormData({
                                    ...formData,
                                    fiche: { ...formData.fiche, date: e.target.value }
                                })}
                                InputLabelProps={{ shrink: true }}
                                fullWidth
                                margin="normal"
                            />
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                label="Date de fin"
                                type="date"
                                value={formData.fiche.date2}
                                onChange={(e) => setFormData({
                                    ...formData,
                                    fiche: { ...formData.fiche, date2: e.target.value }
                                })}
                                InputLabelProps={{ shrink: true }}
                                fullWidth
                                margin="normal"
                            />
                        </Grid>

                        <Grid item xs={6}>
                            <Button variant="contained" onClick={() => setOpenObsDialog(true)}>
                                Co-Observateurs
                            </Button>
                        </Grid>
                        <Grid item xs={6}><Typography sx={{ fontStyle: 'italic', fontSize: '0.8rem' }}>
                            {selectedObservateursNames}</Typography>
                        </Grid>
                    </Grid>
                    <FormControl fullWidth margin="normal">
                        <InputLabel>Organisme</InputLabel>
                        <Select
                            value={formData.fiche.organisme}
                            onChange={(e) => setFormData({
                                ...formData,
                                fiche: { ...formData.fiche, organisme: e.target.value }
                            })}
                        >
                            {organismes.map((org) => (
                                <MenuItem key={org.idorg} value={org.idorg}>{org.organisme}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <FormControl fullWidth margin="normal">
                        <InputLabel>Etude</InputLabel>
                        <Select
                            value={formData.fiche.etude}
                            onChange={(e) => setFormData({
                                ...formData,
                                fiche: { ...formData.fiche, etude: e.target.value }
                            })}
                        >
                            {etudes.map((et) => (
                                <MenuItem key={et.idetude} value={et.idetude}>{et.etude}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <Grid container spacing={2} direction="row" justifyContent="center" alignItems="center">
                        <Grid item xs={6}>
                            <FormControl margin="normal">
                                <Typography>Type de donnée</Typography>
                                <Switch
                                    checked={formData.fiche.typeDonnee === 'Pr'}
                                    onChange={(e) => setFormData({
                                        ...formData,
                                        fiche: { ...formData.fiche, typeDonnee: e.target.checked ? 'Pr' : 'Pu' }
                                    })}
                                />
                                <Typography>{formData.fiche.typeDonnee === 'Pr' ? 'Privé' : 'Public'}</Typography>
                            </FormControl>
                        </Grid>
                        <Grid item xs={6}>
                            <FormControl fullWidth margin="normal">
                                <InputLabel>Diffusion</InputLabel>
                                <Select
                                    value={formData.fiche.diffusion}
                                    onChange={(e) => setFormData({
                                        ...formData,
                                        fiche: { ...formData.fiche, diffusion: e.target.value }
                                    })}
                                >
                                    <MenuItem value="Point">Point</MenuItem>
                                    <MenuItem value="Maille">Maille</MenuItem>
                                    <MenuItem value="Commune">Commune</MenuItem>
                                    <MenuItem value="Département">Département</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                    </Grid>

                    <Box sx={{ display: 'flex', justifyContent: 'space-between', margin: 2 }}>
                        <Grid container spacing={2}>

                            <Grid item xs={6}>
                                <Button variant="outlined" color="bleunuit" onClick={onCancel}>
                                    Retour carte
                                </Button>
                            </Grid>
                            <Grid item xs={6}>
                                <Button variant="contained" color="secondary" type="submit">
                                    Saisir des Obs
                                </Button>
                            </Grid>
                        </Grid>
                    </Box>
                </form>
            </Card >
        </Box>
    );
};

export default FicheForm;
