import React, { useContext, useState, useEffect } from 'react';
import {
  BottomNavigation,
  BottomNavigationAction,
  Paper,
  Box,
  Typography,
  Fab,
  Badge,
  Grid
} from '@mui/material';

import HomeIcon from '@mui/icons-material/Home';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import SettingsIcon from '@mui/icons-material/Settings';
import { MainContext } from '../context/MainContext';
import VisibilityIcon from '@mui/icons-material/Visibility';
import { Sync } from '@mui/icons-material';
import { db } from '../db/db';
import { useNavigate } from 'react-router-dom';

export default function Navbar() {
  const { user, fetchUser, obsCount, setObsCount,
    checkDbData, loadingObs, handleUpdateAll, allParam, setAllParam, setLoading,
    phase, setPhase } = useContext(MainContext);
  const [value, setValue] = useState(2);
  const navigate = useNavigate();

  const renderContent = () => {
    const contentStyle = {
      marginTop: 6,
      marginRight: 2,
      display: 'flex',
      justifyContent: 'flex-end',
      alignItems: 'center',
      textAlign: 'right',
    };
    // Vérification de la condition sur `phase`
    if (phase) {
      let message = '';
      switch (phase) {
        case 'map':
          message = 'Choisir la localisation';
          break;
        case 'fiche':
          message = 'Renseigner la fiche d\'obs';
          break;
        case 'observation':
          message = 'Choisissez l\'espèce';
          break;
        default:
          message = phase; // Affiche la valeur de `phase` si elle ne correspond à aucun cas
      }

      return (
        <Box sx={contentStyle}>
          <Typography variant="h5">{message}</Typography>
        </Box>
      );
    }

    switch (value) {
      case 2:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">LannObs'Go 🌿</Typography>
          </Box>
        );
      case 3:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">Synchronisation</Typography>
          </Box>
        );
      case 1:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">Mes Observations</Typography>
          </Box>
        );
      case 0:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">Paramètres</Typography>
          </Box>
        );
      default:
        return (
          <Box sx={contentStyle}>
            <Typography variant="h5">LannObs'Go 🌿</Typography>
          </Box>
        );
    }
  };

  //pour déclencher le compte des obs
  useEffect(() => {
    fetchUser();
    const fetchObsCount = async () => {
      try {
        const count = await db.obs.count();
        setObsCount(count);
      } catch (error) {
        console.error('Erreur lors de la récupération du nombre de lignes dans obs:', error);
      }
    };
    fetchObsCount();
  }, []);



  return (
    <Box sx={{ width: '100vw', overflowX: 'hidden' }} >
      <Grid container spacing={2}>
        <Grid item xs={2} md={2}>
          <img src={`${process.env.PUBLIC_URL}/images/Langazel-LOGO.png`}
            alt="Préférences 1"
            style={{ height: '80px', paddingLeft: 8, paddingTop: 8 }} />
        </Grid>
        <Grid item xs={10} md={10}>
          {renderContent()}
        </Grid>
      </Grid>


      {/* Bottom Navigation */}
      <Paper
        sx={{
          position: 'fixed',
          bottom: 0,
          left: 0,
          width: '100%',
          right: 0,
          zIndex: 10,
          height: '70px',
          overflowX: 'hidden',
        }}
        elevation={3}
      >
        <BottomNavigation
          showLabels
          value={value}
          onChange={(event, newValue) => {
            setValue(newValue);
          }}
          sx={{
            height: '100%',
            width: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-around',
            m: 0,
            p: 0,
          }}
        >
          <BottomNavigationAction
            label="Paramètres"
            onClick={() => { navigate('/parametre'); setPhase(''); setLoading(false) }}
            sx={{ minWidth: 0, padding: 0 }}
            icon={
              <Badge color="error" variant="dot" invisible={allParam === 'oui'}>
                <SettingsIcon style={{ fontSize: 30 }} />
              </Badge>
            }
          />
          <BottomNavigationAction
            label="Obs'"
            onClick={() => { navigate('/obs'); setPhase('') }}
            sx={{ minWidth: 0, padding: 0 }}
            icon={
              <Badge badgeContent={obsCount} >
                <VisibilityIcon style={{ fontSize: 30 }} />
              </Badge>
            }
          />
          <BottomNavigationAction label="Accueil" icon={<HomeIcon
            style={{ fontSize: 30 }} />}
            onClick={() => { navigate('/'); setPhase('') }}
            sx={{ minWidth: 0, padding: 0 }} />

          <BottomNavigationAction label="Synchro" icon={<Sync
            style={{ fontSize: 30 }} />}
            onClick={() => { navigate('/synchro'); setPhase('') }}
            sx={{ minWidth: 0, padding: 0 }} />
        </BottomNavigation>
      </Paper>
    </Box>
  );
}
