import React, { useState, useEffect } from 'react';
import {
    TextField,
    Button,
    Stack,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Typography,
    Card,
    CardMedia,
    LinearProgress,
} from '@mui/material';
import { db } from '../db/db';
import Snackbar from '@mui/material/Snackbar';
import MuiAlert from '@mui/material/Alert';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import { IconButton, Tooltip } from '@mui/material';
import PhotoCamera from '@mui/icons-material/PhotoCamera';
import SaveIcon from '@mui/icons-material/Save';
import FolderIcon from '@mui/icons-material/Folder';


const Alert = React.forwardRef(function Alert(props, ref) {
    return <MuiAlert elevation={6} ref={ref} variant="filled" {...props} />;
});

const resizeImage = (file, maxLength, quality = 0.7) => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        const reader = new FileReader();

        reader.onload = (e) => {
            img.src = e.target.result;
        };

        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            let width = img.width;
            let height = img.height;

            // Redimensionner en gardant le ratio sur la plus grande longueur
            if (width > height && width > maxLength) {
                height = (height * maxLength) / width;
                width = maxLength;
            } else if (height >= width && height > maxLength) {
                width = (width * maxLength) / height;
                height = maxLength;
            }

            canvas.width = Math.round(width);
            canvas.height = Math.round(height);
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

            canvas.toBlob(
                (blob) => {
                    resolve({ blob, size: maxLength });
                },
                'image/jpeg',
                quality
            );
        };

        img.onerror = reject;
        reader.readAsDataURL(file);
    });
};


const generateMultipleSizes = async (file) => {
    const sizes = [800, 400, 200];
    const images = [];

    for (let size of sizes) {
        const resized = await resizeImage(file, size, 0.7);
        images.push({ size: resized.size, blob: resized.blob });
    }

    return images;
};
export default function ImageForm() {
    const [text, setText] = useState('');
    const [commune, setCommune] = useState('');
    const [observatoire, setObservatoire] = useState('');
    const [date, setDate] = useState(null);
    const [file, setFile] = useState(null);
    const [previewUrl, setPreviewUrl] = useState(null);
    const [observatoireData, setObservatoireData] = useState([]);
    const [loading, setLoading] = useState(false);
    const [communes, setCommunes] = useState([]);
    const [photos, setPhotos] = useState([]);
    const [editingId, setEditingId] = useState(null);
    const [openSnackbar, setOpenSnackbar] = useState(false);
    const [snackbarMessage, setSnackbarMessage] = useState('');
    const [snackbarSeverity, setSnackbarSeverity] = useState('success'); // ou 'error'
    const [existingImages, setExistingImages] = useState(null);


    // Effect hook pour récupérer les données de la base de données à l'initialisation
    useEffect(() => {
        const fetchData = async () => {
            const obs = await db.observatoire.toArray();  // Récupérer les observatoires
            const com = await db.commune.toArray();  // Récupérer les communes
            const photosData = await db.photodet.toArray();  // Récupérer les photos déjà enregistrées
            console.log('photosData', photosData);
            // Ajouter un observatoire par défaut
            const obsWithDefault = [
                ...obs,
                { id: 'nr', titre: 'ne sais pas', nomvar: 'NR' }
            ];

            setObservatoireData(obsWithDefault);
            setCommunes(com);
            setPhotos(photosData);
        };
        fetchData();  // Appel de la fonction pour récupérer les données
    }, []);

    // Fonction pour gérer le changement de fichier d'image
    const handleFileChange = (e) => {
        const selectedFile = e.target.files[0];
        setFile(selectedFile);
        if (selectedFile) {
            setPreviewUrl(URL.createObjectURL(selectedFile));  // Générer l'URL pour la prévisualisation
        }
    };

    // Fonction pour supprimer une photo enregistrée
    const handleDelete = async (id) => {
        await db.photodet.delete(id);  // Supprimer la photo de la base de données
        const updated = await db.photodet.toArray();  // Récupérer la liste mise à jour des photos
        setPhotos(updated);
    };

    // Fonction pour charger les données d'une photo en mode édition
    const handleEdit = (item) => {
        setObservatoire(observatoireData.find(o => o.nomvar === item.observa));
        setCommune(communes.find(c => c.codecom === item.codecom));
        setText(item.text);
        setDate(item.date ? new Date(item.date) : null);
        setEditingId(item.id);

        // Préparer l'image pour la prévisualisation si elle existe
        const imageData = item.images.find(img => img.width === 200);
        if (imageData) {
            const blob = new Blob([new Uint8Array(imageData.data)], { type: 'image/jpeg' });
            const imageUrl = URL.createObjectURL(blob);
            setPreviewUrl(imageUrl);
        }

        // Charger les images existantes pour ne pas les perdre lors de l'édition
        setExistingImages(item.images);
    };

    // Fonction pour soumettre le formulaire
    const handleSubmit = async () => {
        // Vérifier que tous les champs sont remplis, sauf l'image si on édite
        if ((!file && !existingImages) || !date || !observatoire || !commune) {
            return alert('Remplir tous les champs.');
        }

        setLoading(true);
        let imageArray;

        // Si un nouveau fichier est sélectionné, on génère les nouvelles tailles d'images
        if (file) {
            const resizedImages = await generateMultipleSizes(file);
            imageArray = await Promise.all(
                resizedImages.map(async ({ size, blob }) => {
                    const arrayBuffer = await blob.arrayBuffer();
                    return {
                        size,
                        data: new Uint8Array(arrayBuffer),
                    };
                })
            );
        } else {
            // Sinon, on utilise les images existantes
            imageArray = existingImages;
        }

        const currentDate = new Date().toISOString().split('T')[0];

        // Créer l'objet de données à enregistrer
        const data = {
            observatoire: observatoire.titre,
            observa: observatoire.nomvar,
            commune: commune.commune,
            codecom: commune.codecom,
            text,
            date: date.toISOString().split('T')[0],
            datesaisi: currentDate,
            images: imageArray,
        };

        // Si nous sommes en mode édition, mettre à jour l'enregistrement
        if (editingId) {
            await db.photodet.update(editingId, data);
            setEditingId(null);
        } else {
            // Sinon, ajouter un nouvel enregistrement
            await db.photodet.add(data);
        }

        // Mettre à jour la liste des photos
        const updatedPhotos = await db.photodet.toArray();
        setPhotos(updatedPhotos);

        // Afficher un message de succès
        setSnackbarMessage("Données enregistrées avec succès !");
        setSnackbarSeverity("success");
        setOpenSnackbar(true);

        // Réinitialiser les champs du formulaire
        setText('');
        setDate(null);
        setFile(null);
        setPreviewUrl(null);
        setObservatoire('');
        setCommune('');
        setLoading(false);
    };



    return (
        <Stack spacing={2} sx={{ maxWidth: '95vw', margin: 'auto', mt: 4, marginTop: 4, paddingBottom: 16 }}
        >
            {loading && <LinearProgress />}
            <Typography variant="h6">Demande d'aide pour la détermination</Typography>
            <FormControl fullWidth disabled={loading}>
                <InputLabel id="titre-label">Groupe d'espèces</InputLabel>
                <Select
                    labelId="titre-label"
                    value={observatoire?.id || ''}
                    label="Groupe d'espèces"
                    onChange={(e) => {
                        const selected = observatoireData.find(item => item.id === e.target.value);
                        setObservatoire(selected);
                    }}
                >
                    {observatoireData.map((item) => (
                        <MenuItem key={item.id} value={item.id}>
                            {item.titre}
                        </MenuItem>
                    ))}
                </Select>
            </FormControl>
            <FormControl fullWidth disabled={loading}>
                <InputLabel id="commune-label">Commune</InputLabel>
                <Select
                    labelId="commune-label"
                    value={commune?.id || ''}
                    label="Commune"
                    onChange={(e) => {
                        const selected = communes.find(item => item.id === e.target.value);
                        setCommune(selected);
                    }}
                >
                    {communes.map((item) => (
                        <MenuItem key={item.id} value={item.id}>
                            {item.commune}
                        </MenuItem>
                    ))}
                </Select>
            </FormControl>
            <TextField
                label="Date"
                type="date"
                value={date ? date.toISOString().split('T')[0] : ''}
                onChange={(e) => setDate(new Date(e.target.value))}
                InputLabelProps={{ shrink: true }}
                disabled={loading}
            />
            <TextField
                label="Commentaire"
                value={text}
                onChange={(e) => setText(e.target.value)}
                disabled={loading}
            />
            <Button variant="contained" component="label" disabled={loading} startIcon={<SaveIcon />}>
                Choisir une photo
                <input
                    type="file"
                    accept="image/*"
                    hidden
                    onChange={handleFileChange}
                />
            </Button>
            <Button variant="contained" component="label" disabled={loading}
                startIcon={<PhotoCamera />}>
                Prendre une photo
                <input
                    type="file"
                    accept="image/*"
                    capture="environment"
                    hidden
                    onChange={handleFileChange}
                />
            </Button>

            {previewUrl && (
                <Card>
                    <CardMedia
                        component="img"
                        height="200"
                        image={previewUrl}
                        alt="Prévisualisation"
                    />
                </Card>
            )}

            <Button variant="contained" color="primary" onClick={handleSubmit} disabled={loading}
                startIcon={<SaveIcon />}>
                Enregistrer
            </Button>
            {photos.length > 0 && (
                <Stack spacing={2} mt={4}>
                    <Typography variant="h6">Éléments enregistrés</Typography>
                    <Typography >Pensez à les synchroniser pour qu'ils soient envoyés sur LannObs</Typography>
                    {photos.map((item) => (
                        <Card sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2, p: 1 }}>
                            {/* Vignette */}
                            <CardMedia
                                component="img"
                                height="60"
                                image={(() => {
                                    const image = item.images.find(img => img.size === 200);
                                    if (image && image.data) {
                                        // Convertir les données en Base64
                                        const base64String = btoa(String.fromCharCode(...new Uint8Array(image.data)));
                                        return `data:image/jpeg;base64,${base64String}`;
                                    }
                                    // Retourner une image par défaut si aucune image n'est trouvée
                                    return 'path/to/default/image.jpg';
                                })()}
                                alt="vignette"
                                sx={{ width: 60, height: 60, objectFit: 'cover', borderRadius: 1 }}
                            />

                            {/* Infos */}
                            <Stack spacing={0.5}>
                                <Typography variant="body1" fontWeight="bold">{item.observatoire}</Typography>
                                <Typography variant="body2" color="text.secondary">
                                    {item.commune} – {new Date(item.date).toLocaleDateString()}
                                </Typography>
                                <Typography variant="body2">{item.text}</Typography>
                            </Stack>

                            {/* Boutons */}
                            <Stack spacing={1} direction="row" sx={{ marginLeft: 'auto' }}>
                                <Tooltip title="Supprimer">
                                    <IconButton color="error" onClick={() => handleDelete(item.id)}>
                                        <DeleteIcon />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip title="Modifier">
                                    <IconButton color="primary" onClick={() => handleEdit(item)}>

                                        <EditIcon />
                                    </IconButton>
                                </Tooltip>

                            </Stack>
                        </Card>

                    ))}
                </Stack>
            )}
            <Snackbar
                open={openSnackbar}
                autoHideDuration={3000}
                onClose={() => setOpenSnackbar(false)}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
            >
                <Alert onClose={() => setOpenSnackbar(false)} severity={snackbarSeverity} sx={{ width: '100%' }}>
                    {snackbarMessage}
                </Alert>
            </Snackbar>
        </Stack>
    );
}
