import React, { useContext, useState } from 'react';
import Card from '@mui/material/Card';
import CardActions from '@mui/material/CardActions';
import CardContent from '@mui/material/CardContent';
import Button from '@mui/material/Button';
import TextField from '@mui/material/TextField';
import Typography from '@mui/material/Typography';
import { db } from '../db/db';
import { MainContext } from '../context/MainContext';
import { Alert, Box, Grid } from '@mui/material';
import { useNavigate } from 'react-router-dom';


export default function LoginForm({ }) {
    const { fetchUser } = useContext(MainContext);
    const [status, setStatus] = useState('');
    const [id, setId] = useState('');
    const navigate = useNavigate();
    const apiBaseUrl = process.env.REACT_APP_API_BASE_URL;

    const handleInputChange = (event) => {
        const input = event.target.value.toUpperCase(); // Convertir en majuscules
        if (input.length <= 5) { // Limiter à 5 caractères
            setId(input);
        }
    };

    const handleSubmit = async (event) => {
        event.preventDefault();
        try {
            await requestUser(id);
            navigate('/parametre');
        } catch (error) {
            setStatus(`Erreur : ${error.message}`);
        }
    };

    async function requestUser(id) {
        await db.user.clear();
        const response = await fetch(`${apiBaseUrl}/api/v1/user?resourceid=${id}`, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            }
        });

        if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            throw new Error(errData.message || `Identifiant introuvable (${response.status})`);
        }

        const data = await response.json();

        if (!data.idmembre) {
            throw new Error('Réponse invalide du serveur');
        }

        await db.user.add({
            nom: data.nom,
            prenom: data.prenom,
            idmembre: data.idmembre,
            idobser: data.idobser,
            droits: data.droits
        });

        fetchUser();
    }


    return (
        <Box
            sx={{
                backgroundImage: `url(${process.env.PUBLIC_URL + '/images/lannobsgo-bg2.jpg'})`, backgroundSize: 'cover',
                backgroundPosition: 'top',
                backgroundRepeat: 'no-repeat',
                paddingBottom: 8, paddingTop: 8,
            }}>
            <Grid container spacing={3} justifyContent="center" alignItems="center" >
                <Grid item xs={12}

                >
                    <Card elevation={3} sx={{
                        p: 2,
                        backgroundColor: 'transparent',
                        boxShadow: 'none',
                    }}>
                        <Alert severity="info" sx={{ mb: 2 }}>
                            <Typography variant="body1" component="div">
                                Pour vous connecter, récupérez votre ID d'utilisateur :
                                <ul style={{ marginTop: 8, paddingLeft: 20 }}>
                                    <li>Sur le site, en haut à droite, cliquez sur votre nom</li>
                                    <li>Choisissez <strong>"Vos Préférences"</strong></li>
                                    <li>Votre identifiant unique se trouve en haut à gauche</li>
                                </ul>
                            </Typography>
                        </Alert>
                        <Grid container spacing={2}>
                            <Grid item xs={12} md={6}>
                                <img src={`${process.env.PUBLIC_URL}/images/param.png`}
                                    alt="Préférences 1" style={{ borderRadius: 2 }} />
                            </Grid>
                            <Grid item xs={12} md={6}>
                                <img src={`${process.env.PUBLIC_URL}/images/identifiant.png`}
                                    alt="Préférences 2" style={{ borderRadius: 2 }} />
                            </Grid>
                        </Grid>
                    </Card>
                </Grid>

                <Grid item xs={12} md={6}>
                    <Card elevation={3} sx={{ p: 3 }}>
                        <form onSubmit={handleSubmit}>
                            <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Connexion
                                </Typography>
                                <TextField
                                    fullWidth
                                    label="Identifiant"
                                    name="Identifiant"
                                    value={id}
                                    onChange={handleInputChange}
                                    inputProps={{ maxLength: 5 }}
                                    sx={{ textTransform: 'uppercase', mt: 2 }}
                                />
                            </CardContent>
                            <CardActions sx={{ justifyContent: 'flex-end' }}>
                                <Button variant="contained" color="primary" type="submit" size="medium">
                                    Valider
                                </Button>
                            </CardActions>
                            {status && (
                                <Typography variant="body2" color="error" sx={{ mt: 2 }}>
                                    {status}
                                </Typography>
                            )}
                        </form>
                    </Card>
                </Grid>
            </Grid>
        </Box>
    );
}
